type MergeExecutionCanonicalOrderKey = (LaneId, DataSpaceId, Hash, u64, u64, u64, Hash, Hash);

fn merge_execution_canonical_order_key(
    proposal: &iroha_data_model::block::consensus::LaneBlockProposalV1,
) -> MergeExecutionCanonicalOrderKey {
    let descriptor = &proposal.descriptor;
    (
        descriptor.lane_id,
        descriptor.dataspace_id,
        descriptor.lane_incarnation,
        descriptor.lane_block_height,
        descriptor.proposal_height,
        descriptor.lane_block_view,
        descriptor.descriptor_hash,
        proposal.proposal_hash,
    )
}

fn merge_execution_source_bundle_hash(source_bundle: &[u8]) -> Hash {
    Hash::new_from_chunks(&[
        b"iroha:nexus:autonomous-lane-merge-bundle:v1\0",
        source_bundle,
    ])
}

fn merge_origin_proposal_matches_current(execution: &MergeLaneExecution) -> bool {
    let origin = &execution.origin_proposal;
    let current = &execution.proposal;
    let left = &origin.descriptor;
    let right = &current.descriptor;
    left.lane_block_view == 0
        && origin.payload_block_hint == current.payload_block_hint
        && left.lane_id == right.lane_id
        && left.dataspace_id == right.dataspace_id
        && left.lane_incarnation == right.lane_incarnation
        && left.proposal_height == right.proposal_height
        && left.previous_lane_block_height == right.previous_lane_block_height
        && left.previous_lane_block_descriptor_hash == right.previous_lane_block_descriptor_hash
        && left.lane_block_height == right.lane_block_height
        && left.subject_hash == right.subject_hash
        && left.payload_ownership_hash == right.payload_ownership_hash
        && left.rbc_instance_hash == right.rbc_instance_hash
        && left.accepted_candidate_indices == right.accepted_candidate_indices
        && left.accepted_transaction_hashes == right.accepted_transaction_hashes
        && left.validator_set_hash_version == right.validator_set_hash_version
        && left.validator_set_hash == right.validator_set_hash
        && left.validator_set == right.validator_set
        && left.validator_count == right.validator_count
        && left.min_quorum == right.min_quorum
        && left.qc_mode_tag == right.qc_mode_tag
}

fn preflight_canonical_merge_inner_frame(
    encoded: &[u8],
    maximum: usize,
    kind: &'static str,
) -> Result<(), MergeLedgerCommitError> {
    if encoded.len() > maximum {
        return Err(MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "encoded {kind} exceeds the hard byte limit"
        )));
    }
    if encoded.len() < norito::core::Header::SIZE
        || encoded.get(..norito::core::MAGIC.len()) != Some(norito::core::MAGIC.as_slice())
    {
        return Err(MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "encoded {kind} is not valid exact framed Norito"
        )));
    }
    if encoded.get(MERGE_INNER_NORITO_COMPRESSION_OFFSET)
        != Some(&(norito::Compression::None as u8))
    {
        return Err(MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "encoded {kind} must use uncompressed exact framed Norito"
        )));
    }
    let declared_length = encoded
        .get(MERGE_INNER_NORITO_LENGTH_OFFSET..MERGE_INNER_NORITO_LENGTH_OFFSET + 8)
        .and_then(|raw| <[u8; 8]>::try_from(raw).ok())
        .map(u64::from_le_bytes)
        .ok_or_else(|| {
            MergeLedgerCommitError::ExecutionBatchInvalid(format!(
                "encoded {kind} is not valid exact framed Norito"
            ))
        })?;
    if declared_length > u64::try_from(maximum).unwrap_or(u64::MAX) {
        return Err(MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "encoded {kind} exceeds the hard byte limit"
        )));
    }
    Ok(())
}

fn decode_canonical_merge_reservation_key(
    encoded: &[u8],
) -> Result<crate::queue::LaneQueueReservationKeyV2, MergeLedgerCommitError> {
    preflight_canonical_merge_inner_frame(
        encoded,
        MAX_MERGE_EXECUTION_RESERVATION_KEY_BYTES,
        "lane reservation key",
    )?;
    let decoded = norito::decode_canonical::<crate::queue::LaneQueueReservationKeyV2>(encoded)
        .map_err(|error| {
            MergeLedgerCommitError::ExecutionBatchInvalid(format!(
                "encoded lane reservation key is not canonical exact framed Norito: {error}"
            ))
        })?;
    decoded.validate().map_err(|reason| {
        MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "encoded lane reservation key failed validation: {reason}"
        ))
    })?;
    Ok(decoded)
}

fn decode_canonical_merge_routing_plan(
    encoded: &[u8],
) -> Result<crate::queue::RoutingPlan, MergeLedgerCommitError> {
    preflight_canonical_merge_inner_frame(
        encoded,
        MAX_MERGE_EXECUTION_ROUTING_PLAN_BYTES,
        "routing plan",
    )?;
    norito::decode_canonical::<crate::queue::RoutingPlan>(encoded).map_err(|error| {
        MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "encoded routing plan is not canonical exact framed Norito: {error}"
        ))
    })
}

/// Return the transaction-membership hashes committed by an execution batch.
pub(crate) fn merge_execution_committed_transaction_hashes(
    batch: &MergeExecutionBatch,
) -> Vec<HashOf<SignedTransaction>> {
    batch
        .lanes
        .iter()
        .flat_map(|execution| committed_transaction_hashes_for_entrypoints(&execution.entrypoints))
        .collect()
}

/// Return committed transaction-membership hashes for an ordered entrypoint slice.
///
/// The all-external fast path preserves the canonical signed-transaction hash;
/// heterogeneous system entrypoints use their typed entrypoint identities.
pub(crate) fn committed_transaction_hashes_for_entrypoints(
    entrypoints: &[TransactionEntrypoint],
) -> Vec<HashOf<SignedTransaction>> {
    if entrypoints
        .iter()
        .all(|entrypoint| matches!(entrypoint, TransactionEntrypoint::External(_)))
    {
        return entrypoints
            .iter()
            .filter_map(|entrypoint| match entrypoint {
                TransactionEntrypoint::External(tx) => {
                    Some(crate::tx::AcceptedTransaction::prepare_signed_metadata(tx).signed_hash)
                }
                _ => None,
            })
            .collect();
    }
    entrypoints
        .iter()
        .map(|entrypoint| {
            HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::from(entrypoint.hash()))
        })
        .collect()
}

/// Decode the exact queue-reservation groups finalized by a certified merge entry.
///
/// The outer vector retains canonical lane order and every inner vector retains
/// exact entrypoint/FIFO order. Canonical decoding, transaction binding, and
/// cross-lane uniqueness are rechecked before any caller can begin Queue
/// cleanup, so a malformed later group cannot partially consume an earlier
/// group.
pub(crate) fn certified_merge_queue_reservation_groups(
    entry: &MergeLedgerEntry,
) -> Result<
    Vec<
        Vec<(
            HashOf<SignedTransaction>,
            crate::queue::LaneQueueReservationKeyV2,
        )>,
    >,
    MergeLedgerCommitError,
> {
    let Some(batch) = entry.execution_batch.as_ref() else {
        return Ok(Vec::new());
    };
    let mut seen_transactions = BTreeSet::new();
    let mut seen_reservations = BTreeSet::new();
    let mut groups = Vec::with_capacity(batch.lanes.len());
    for execution in &batch.lanes {
        let transaction_hashes =
            committed_transaction_hashes_for_entrypoints(&execution.entrypoints);
        if transaction_hashes.len() != execution.reservation_keys.len() {
            return Err(MergeLedgerCommitError::ExecutionBatchInvalid(
                "merge queue reservation vector is not aligned with entrypoints".to_owned(),
            ));
        }
        let mut reservations = Vec::with_capacity(execution.reservation_keys.len());
        for (transaction_hash, encoded) in transaction_hashes
            .into_iter()
            .zip(&execution.reservation_keys)
        {
            let reservation = decode_canonical_merge_reservation_key(encoded)?;
            if reservation.signed_transaction_hash != transaction_hash
                || !seen_transactions.insert(transaction_hash)
                || !seen_reservations.insert(reservation.digest())
            {
                return Err(MergeLedgerCommitError::ExecutionBatchInvalid(
                    "merge queue reservation is duplicated or bound to another transaction"
                        .to_owned(),
                ));
            }
            reservations.push((transaction_hash, reservation));
        }
        crate::queue::lane_queue_reservation_group_binding_from_ordered_keys(
            reservations.iter().map(|(_, key)| key),
        )
        .map_err(|reason| {
            MergeLedgerCommitError::ExecutionBatchInvalid(format!(
                "merge queue reservation group is invalid: {reason}"
            ))
        })?;
        groups.push(reservations);
    }
    Ok(groups)
}

/// Decode exact queue reservations in canonical lane/entrypoint order.
pub(crate) fn certified_merge_queue_reservations(
    entry: &MergeLedgerEntry,
) -> Result<
    Vec<(
        HashOf<SignedTransaction>,
        crate::queue::LaneQueueReservationKeyV2,
    )>,
    MergeLedgerCommitError,
> {
    Ok(certified_merge_queue_reservation_groups(entry)?
        .into_iter()
        .flatten()
        .collect())
}

/// Errors surfaced when committing merge-ledger entries into state.
#[derive(Debug, ThisError)]
pub enum MergeLedgerCommitError {
    /// Merge entries can only be committed while Nexus is enabled.
    #[error("merge ledger commits require nexus.enabled=true")]
    NexusDisabled,
    /// The merge entry must contain settlement snapshots, an execution batch, or one drain certificate.
    #[error(
        "merge ledger entry must include a lane snapshot, execution batch, or drain certificate"
    )]
    EmptyEntry,
    /// Merge execution batch failed structural or cryptographic validation.
    #[error("merge execution batch is invalid: {0}")]
    ExecutionBatchInvalid(String),
    /// Certified merge entries must be ordered by a canonical global block.
    #[error("certified merge entries require a globally committed carrier block")]
    ExecutionRequiresGlobalBlock,
    /// Merge staging was attempted after another block effect had already been staged.
    #[error("certified merge entry must be staged on a pristine pre-lifecycle block overlay")]
    ExecutionStageNotPristine,
    /// Compact reference sidecar is not locally available for validation.
    #[error("certified merge sidecar {entry_hash} is unavailable")]
    MissingCertifiedMergeSidecar {
        /// Canonical full-entry hash requested by the compact reference.
        entry_hash: HashOf<MergeLedgerEntry>,
    },
    /// Merge execution batch was certified for a different WSV base.
    #[error(
        "merge execution base mismatch: expected height={expected_height} hash={expected_hash}, actual height={actual_height} hash={actual_hash}"
    )]
    ExecutionBaseMismatch {
        /// Height sealed into the batch.
        expected_height: u64,
        /// WSV identity sealed into the batch.
        expected_hash: HashOf<BlockHeader>,
        /// Current committed WSV height.
        actual_height: u64,
        /// Current committed WSV identity.
        actual_hash: HashOf<BlockHeader>,
    },
    /// Durable merge execution marker set is partial or conflicts with the entry.
    #[error("merge execution marker conflict: {0}")]
    ExecutionMarkerConflict(String),
    /// Deterministic re-execution diverged from the committee-certified transcript.
    #[error("merge execution diverged: {0}")]
    ExecutionDivergence(String),
    /// A certified merge entry could not be published to WSV.
    #[error("merge state publication failed: {0}")]
    ExecutionStatePublication(String),
    /// Merge entry referenced a lane absent from the active catalog.
    #[error("merge settlement references unknown lane {lane_id}")]
    UnknownLane {
        /// Lane identifier absent from the active catalog.
        lane_id: LaneId,
    },
    /// Merge entry referenced a lane/dataspace binding that no longer matches the active catalog.
    #[error(
        "merge settlement dataspace mismatch for lane={lane_id}: expected={expected}, actual={actual}"
    )]
    DataspaceMismatch {
        /// Lane identifier being merged.
        lane_id: LaneId,
        /// Dataspace currently bound to the lane.
        expected: DataSpaceId,
        /// Dataspace carried by the merge snapshot.
        actual: DataSpaceId,
    },
    /// Merge entry carried a non-current lane incarnation commitment.
    #[error(
        "merge settlement incarnation mismatch for lane={lane_id}: expected={expected:?}, actual={actual:?}"
    )]
    LaneIncarnationMismatch {
        /// Lane identifier being merged.
        lane_id: LaneId,
        /// Current active incarnation commitment.
        expected: Hash,
        /// Incarnation carried by the merge snapshot or relay.
        actual: Hash,
    },
    /// Merge entry referenced a dataspace absent from the active catalog.
    #[error("merge settlement references unknown dataspace {dataspace_id}")]
    UnknownDataspace {
        /// Dataspace identifier absent from the active catalog.
        dataspace_id: DataSpaceId,
    },
    /// Lane snapshots must be sorted by `(lane_id, dataspace_id)` and unique.
    #[error(
        "merge ledger lane snapshots must be unique and sorted: previous={previous_lane}:{previous_dataspace}, current={current_lane}:{current_dataspace}"
    )]
    LaneSnapshotOrderViolation {
        /// Previous lane identifier encountered while walking the entry payload.
        previous_lane: LaneId,
        /// Previous dataspace identifier encountered while walking the entry payload.
        previous_dataspace: DataSpaceId,
        /// Current lane identifier that violated strict ordering.
        current_lane: LaneId,
        /// Current dataspace identifier that violated strict ordering.
        current_dataspace: DataSpaceId,
    },
    /// Merge QC epoch does not match the entry epoch.
    #[error("merge ledger qc epoch mismatch: entry={entry_epoch}, qc={qc_epoch}")]
    MergeQCEpochMismatch {
        /// Epoch embedded in the merge entry.
        entry_epoch: u64,
        /// Epoch embedded in the merge QC.
        qc_epoch: u64,
    },
    /// Merge QC digest does not match the entry payload.
    #[error("merge ledger qc digest mismatch: expected={expected}, actual={actual}")]
    MergeQCDigestMismatch {
        /// Expected digest computed from the entry payload.
        expected: iroha_crypto::Hash,
        /// Digest supplied by the merge QC.
        actual: iroha_crypto::Hash,
    },
    /// Merge QC was produced for a different chain.
    #[error("merge ledger qc chain id digest mismatch: expected={expected}, actual={actual}")]
    MergeQCChainIdMismatch {
        /// Digest derived from the local chain identifier.
        expected: Hash,
        /// Digest embedded in the historical QC.
        actual: Hash,
    },
    /// Merge QC uses an unsupported validator-set hash version.
    #[error("merge ledger qc validator-set hash version {0} is unsupported")]
    MergeQCValidatorSetHashVersion(u16),
    /// Merge QC validator-set hash does not match its embedded roster.
    #[error("merge ledger qc validator-set hash mismatch")]
    MergeQCValidatorSetHashMismatch,
    /// Merge QC embedded the same validator more than once.
    #[error("merge ledger qc validator set contains duplicate peer {0}")]
    MergeQCDuplicateValidator(PeerId),
    /// A newly admitted merge QC did not use the authoritative commit topology.
    #[error("merge ledger qc validator set differs from the authoritative commit topology")]
    MergeQCAuthorityMismatch,
    /// Merge QC signer bitmap length does not match the roster length.
    #[error("merge ledger qc signer bitmap length mismatch: expected={expected}, actual={actual}")]
    MergeQCBitmapLengthMismatch {
        /// Expected bitmap length in bytes.
        expected: usize,
        /// Actual bitmap length in bytes.
        actual: usize,
    },
    /// Merge QC signer index exceeds the roster length.
    #[error("merge ledger qc signer index {signer} out of bounds for roster {roster_len}")]
    MergeQCSignerOutOfBounds {
        /// Signer index referenced by the bitmap.
        signer: usize,
        /// Length of the merge committee roster.
        roster_len: usize,
    },
    /// Unused high bits in the final signer bitmap byte were set.
    #[error("merge ledger qc signer bitmap has non-zero padding bits")]
    MergeQCBitmapPadding,
    /// Merge QC signer PoPs do not exactly match the signer bitmap.
    #[error(
        "merge ledger qc signer PoP mismatch at position {position}: expected={expected:?}, actual={actual:?}"
    )]
    MergeQCSignerProofMismatch {
        /// Position within the canonical signer sequence.
        position: usize,
        /// Signer required by the bitmap, if any.
        expected: Option<u32>,
        /// Signer carried by the proof vector, if any.
        actual: Option<u32>,
    },
    /// A signer proof of possession was invalid.
    #[error("merge ledger qc signer {signer} has an invalid BLS proof of possession")]
    MergeQCSignerPopInvalid {
        /// Signer index whose PoP failed.
        signer: u32,
    },
    /// Merge QC does not meet the quorum threshold.
    #[error("merge ledger qc quorum not met: observed={observed}, required={required}")]
    MergeQCInsufficientQuorum {
        /// Number of signers observed.
        observed: usize,
        /// Minimum quorum required.
        required: usize,
    },
    /// Merge QC did not include an aggregate signature.
    #[error("merge ledger qc aggregate signature missing")]
    MergeQCAggregateSignatureMissing,
    /// Merge QC aggregate signature failed verification.
    #[error("merge ledger qc aggregate signature invalid")]
    MergeQCAggregateSignatureInvalid,
    /// Merge QC requires a non-empty merge committee roster.
    #[error("merge ledger qc requires a non-empty commit topology roster")]
    MergeQCEmptyRoster,
    /// Merge entry epoch must advance by exactly one.
    #[error("merge ledger epoch must be contiguous: expected={expected}, attempted={attempted}")]
    NonMonotonicEpoch {
        /// Exact next merge epoch.
        expected: u64,
        /// Epoch carried by the attempted entry.
        attempted: u64,
    },
    /// Historical merge entry catalog differs from the active admission catalog.
    #[error("merge ledger entry catalog does not match the active lane catalog")]
    CatalogMismatch,
    /// Historical snapshot was proposed before its incarnation became active.
    #[error(
        "merge lane snapshot proposal height {proposal_height} is not after activation height {activation_height} for lane {lane_id}"
    )]
    LaneIncarnationNotActive {
        /// Lane referenced by the snapshot.
        lane_id: LaneId,
        /// Proposal height sealed into the snapshot.
        proposal_height: u64,
        /// Activation boundary sealed into the snapshot.
        activation_height: u64,
    },
    /// Embedded settlement commitment or hash does not match the lane snapshot.
    #[error("merge lane snapshot embeds an invalid settlement commitment for lane {lane_id}")]
    SettlementCommitmentMismatch {
        /// Lane whose settlement commitment was malformed.
        lane_id: LaneId,
    },
    /// Embedded catalog/incarnation/activation history is malformed.
    #[error("merge ledger incarnation context is invalid: {0}")]
    IncarnationContext(String),
    /// Merge entry tried to replay or regress a lane snapshot already merged.
    #[error(
        "merge ledger lane snapshot must advance for lane={lane_id} dataspace={dataspace_id}: latest_height={latest_height}, attempted_height={attempted_height}"
    )]
    NonMonotonicLaneSnapshot {
        /// Lane identifier whose merged height did not advance.
        lane_id: LaneId,
        /// Dataspace identifier paired with the lane.
        dataspace_id: DataSpaceId,
        /// Latest committed lane block height.
        latest_height: u64,
        /// Attempted lane block height.
        attempted_height: u64,
    },
    /// Merge entry tried to skip one or more lane block artifacts.
    #[error(
        "merge ledger lane snapshot must advance contiguously for lane={lane_id} dataspace={dataspace_id}: expected_height={expected_height}, attempted_height={attempted_height}"
    )]
    NonContiguousLaneSnapshot {
        /// Lane identifier whose merged height skipped ahead.
        lane_id: LaneId,
        /// Dataspace identifier paired with the lane.
        dataspace_id: DataSpaceId,
        /// Next admissible lane block height.
        expected_height: u64,
        /// Attempted lane block height.
        attempted_height: u64,
    },
    /// Merge settlement referenced a lane relay that is not available locally.
    #[error(
        "merge settlement missing relay lane={lane_id} dataspace={dataspace_id} height={block_height}"
    )]
    MissingSettlementRelay {
        /// Lane identifier.
        lane_id: LaneId,
        /// Dataspace identifier.
        dataspace_id: DataSpaceId,
        /// Lane block height.
        block_height: u64,
    },
    /// Merge settlement referenced a relay with a different settlement hash.
    #[error(
        "merge settlement hash mismatch for lane={lane_id} dataspace={dataspace_id} height={block_height}"
    )]
    SettlementHashMismatch {
        /// Lane identifier.
        lane_id: LaneId,
        /// Dataspace identifier.
        dataspace_id: DataSpaceId,
        /// Lane block height.
        block_height: u64,
    },
    /// Merge settlement receipt failed deterministic verification.
    #[error("invalid nexus fee receipt: {0}")]
    InvalidNexusFeeReceipt(String),
    /// Merge settlement would duplicate a previously settled receipt.
    #[error("duplicate nexus fee receipt source id {0}")]
    DuplicateNexusFeeReceipt(String),
    /// Merge settlement cannot burn because the payer lacks public XOR.
    #[error(
        "insufficient nexus fee balance for {payer}: requires {required}, available {available}"
    )]
    InsufficientNexusFeeBalance {
        /// Payer account.
        payer: AccountId,
        /// Required aggregate burn amount.
        required: Quantity,
        /// Available balance.
        available: Quantity,
    },
    /// Merge settlement failed while mutating public XOR balances.
    #[error("nexus fee settlement mutation failed: {0}")]
    NexusFeeSettlement(String),
    /// Persistence failure while appending to Kura.
    #[error("merge ledger persistence failed: {0}")]
    Persistence(#[from] crate::kura::Error),
}

/// Controls whether publishing a durable merge cache entry may produce a live pipeline event.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum MergeLedgerPublicationMode {
    /// The entry was just committed by global consensus and may emit its one live event.
    LiveCommit,
    /// The entry is being reconstructed from durable history and must remain silent.
    Replay,
}

/// Bounds which pending merge-entry shapes may be selected for one carrier.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum PendingCertifiedMergeSelection {
    /// Execution and control-only entries are eligible.
    Any,
    /// Only entries without an autonomous execution batch are eligible.
    ControlOnly,
}

impl PendingCertifiedMergeSelection {
    const fn allows_execution(self) -> bool {
        matches!(self, Self::Any)
    }
}

/// Result of comparing one expected QueuePlan admission binding with WSV.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum QueuePlanAdmissionRegistryMatch {
    /// The source identity is not globally admitted yet.
    Absent,
    /// WSV contains the exact same immutable binding.
    Exact,
    /// WSV binds the source identity to another well-formed claim.
    Conflict,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum QueuePlanAdmissionApplicationState {
    /// The obligation is pending on every currently active bound incarnation.
    Pending,
    /// The obligation is coherent but names a retired/recreated incarnation.
    PendingStale,
    /// Canonical transaction membership proves global application.
    Applied,
}

/// Durable disposition of one authenticated pending QueuePlan certificate.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum PendingQueuePlanAdmissionDisposition {
    /// The exact immutable marker is already present in canonical WSV.
    Exact,
    /// No marker exists and the complete certificate is eligible for the next carrier.
    EligibleAbsent,
    /// A different well-formed immutable marker already owns this source identity.
    DefinitiveConflict,
    /// The certificate is authentic but its history, lifecycle, or authority context is stale.
    Stale,
}

/// Compare one exact QueuePlan binding with the immutable WSV admission registry.
///
/// Queue selection uses this bounded lookup while it owns the reservation
/// transition. Malformed keys or values return an error so callers retain the
/// only durable queue owner while failing closed.
pub(crate) fn queue_plan_admission_registry_match(
    state_view: &impl StateReadOnlyWithTransactions,
    entrypoint_hash: HashOf<TransactionEntrypoint>,
    expected_binding_hash: Hash,
) -> Result<QueuePlanAdmissionRegistryMatch, String> {
    let (registry_match, application_state) =
        State::queue_plan_admission_registry_match_with_application_state_in_view(
            state_view,
            entrypoint_hash,
            expected_binding_hash,
        )?;
    if registry_match == QueuePlanAdmissionRegistryMatch::Exact
        && application_state != Some(QueuePlanAdmissionApplicationState::Pending)
    {
        return Err(
            "QueuePlan registry owner is already applied and cannot authorize new Queue ownership"
                .to_owned(),
        );
    }
    Ok(registry_match)
}

impl MergeLedgerPublicationMode {
    const fn emits_live_event(self) -> bool {
        match self {
            Self::LiveCommit => true,
            Self::Replay => false,
        }
    }
}

/// Failures while publishing startup state that was deferred behind snapshot
/// bootstrap authentication.
#[derive(Debug, ThisError)]
pub enum DeferredStartupHydrationError {
    /// Kura has not completed its token-consuming authentication transition.
    #[error("snapshot bootstrap authentication is still pending")]
    SnapshotBootstrapAuthenticationPending,
    /// Durable merge authority failed complete validation.
    #[error("deferred merge-ledger hydration failed: {0}")]
    MergeLedger(#[from] MergeLedgerCommitError),
}

fn validate_merge_snapshot_against_nexus(
    nexus: &iroha_config::parameters::actual::Nexus,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    proposal_height: u64,
) -> Result<(), MergeLedgerCommitError> {
    if !nexus.enabled {
        return Err(MergeLedgerCommitError::NexusDisabled);
    }
    let Some(expected_dataspace) = nexus_catalog_geometry_lane_dataspace(lane_id, nexus) else {
        return Err(MergeLedgerCommitError::UnknownLane { lane_id });
    };
    if expected_dataspace != dataspace_id {
        return Err(MergeLedgerCommitError::DataspaceMismatch {
            lane_id,
            expected: expected_dataspace,
            actual: dataspace_id,
        });
    }
    if nexus.dataspace_catalog.by_id(dataspace_id).is_none() {
        return Err(MergeLedgerCommitError::UnknownDataspace { dataspace_id });
    }
    if !nexus_lane_active_for_authority(lane_id, dataspace_id, nexus, proposal_height) {
        return Err(MergeLedgerCommitError::UnknownLane { lane_id });
    }
    Ok(())
}

fn canonical_merge_settlement_hash(
    settlement: &LaneBlockCommitment,
) -> Result<HashOf<LaneBlockCommitment>, MergeLedgerCommitError> {
    iroha_data_model::nexus::compute_settlement_hash(settlement).map_err(|err| {
        MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "lane {} settlement commitment could not be canonically hashed: {err}",
            settlement.lane_id
        ))
    })
}

fn validate_merge_entry_incarnation_context(
    lane_catalog_hash: Hash,
    active_lanes: &[MergeLaneBinding],
    incarnation_root: Hash,
    activation_root: Hash,
    lane_snapshots: &[MergeLaneSnapshot],
) -> Result<(), MergeLedgerCommitError> {
    if lane_catalog_hash.as_ref().iter().all(|byte| *byte == 0) {
        return Err(MergeLedgerCommitError::IncarnationContext(
            "lane catalog hash must be non-zero".to_owned(),
        ));
    }
    if active_lanes.is_empty()
        || active_lanes
            .windows(2)
            .any(|pair| pair[0].lane_id >= pair[1].lane_id)
    {
        return Err(MergeLedgerCommitError::IncarnationContext(
            "active lane bindings must be non-empty, unique, and ordered by lane id".to_owned(),
        ));
    }
    let mut unique_incarnations = BTreeSet::new();
    for binding in active_lanes {
        if binding.incarnation.as_ref().iter().all(|byte| *byte == 0)
            || binding
                .lane_config_hash
                .as_ref()
                .iter()
                .all(|byte| *byte == 0)
            || binding.activation_height == 0
            || !unique_incarnations.insert(binding.incarnation)
        {
            return Err(MergeLedgerCommitError::IncarnationContext(format!(
                "lane {} has a zero/duplicate configuration or incarnation commitment, or zero activation height",
                binding.lane_id
            )));
        }
    }
    let lifecycle_incarnations = active_lanes
        .iter()
        .map(
            |incarnation| iroha_data_model::nexus::LaneLifecycleIncarnationEntry {
                lane_id: incarnation.lane_id,
                incarnation: incarnation.incarnation,
            },
        )
        .collect::<Vec<_>>();
    let expected_incarnation_root =
        iroha_data_model::nexus::LaneLifecycleParameterV1::incarnation_root(
            &lifecycle_incarnations,
        );
    if incarnation_root != expected_incarnation_root {
        return Err(MergeLedgerCommitError::IncarnationContext(
            "incarnation root does not match the canonical active set".to_owned(),
        ));
    }
    if activation_root != crate::merge::merge_activation_root(active_lanes) {
        return Err(MergeLedgerCommitError::IncarnationContext(
            "activation root does not match the canonical active set".to_owned(),
        ));
    }
    for snapshot in lane_snapshots {
        let binding = active_lanes
            .iter()
            .find(|binding| binding.lane_id == snapshot.lane_id)
            .ok_or(MergeLedgerCommitError::UnknownLane {
                lane_id: snapshot.lane_id,
            })?;
        if binding.dataspace_id != snapshot.dataspace_id {
            return Err(MergeLedgerCommitError::DataspaceMismatch {
                lane_id: snapshot.lane_id,
                expected: binding.dataspace_id,
                actual: snapshot.dataspace_id,
            });
        }
        if binding.incarnation != snapshot.lane_incarnation {
            return Err(MergeLedgerCommitError::LaneIncarnationMismatch {
                lane_id: snapshot.lane_id,
                expected: binding.incarnation,
                actual: snapshot.lane_incarnation,
            });
        }
        if binding.activation_height != snapshot.incarnation_activation_height {
            return Err(MergeLedgerCommitError::IncarnationContext(format!(
                "lane {} snapshot activation height {} does not match active context {}",
                snapshot.lane_id, snapshot.incarnation_activation_height, binding.activation_height
            )));
        }
        if snapshot.proposal_height < binding.activation_height {
            return Err(MergeLedgerCommitError::LaneIncarnationNotActive {
                lane_id: snapshot.lane_id,
                proposal_height: snapshot.proposal_height,
                activation_height: binding.activation_height,
            });
        }
        let settlement = &snapshot.settlement_commitment;
        let settlement_hash = canonical_merge_settlement_hash(settlement)?;
        if settlement.lane_id != snapshot.lane_id
            || settlement.lane_incarnation != snapshot.lane_incarnation
            || settlement.dataspace_id != snapshot.dataspace_id
            || settlement.block_height != snapshot.lane_block_height
            || settlement_hash != snapshot.settlement_hash
        {
            return Err(MergeLedgerCommitError::SettlementCommitmentMismatch {
                lane_id: snapshot.lane_id,
            });
        }
    }
    Ok(())
}

fn validate_merge_entry_snapshot_order(
    lane_snapshots: &[MergeLaneSnapshot],
) -> Result<(), MergeLedgerCommitError> {
    let mut previous = None;
    for snapshot in lane_snapshots {
        let current = (snapshot.lane_id, snapshot.dataspace_id);
        if let Some(previous) = previous
            && current <= previous
        {
            return Err(MergeLedgerCommitError::LaneSnapshotOrderViolation {
                previous_lane: previous.0,
                previous_dataspace: previous.1,
                current_lane: current.0,
                current_dataspace: current.1,
            });
        }
        previous = Some(current);
    }
    Ok(())
}

fn validate_merge_snapshot_carrier_bounds(
    carrier_height: u64,
    lane_snapshots: &[MergeLaneSnapshot],
) -> Result<(), MergeLedgerCommitError> {
    if let Some(snapshot) = lane_snapshots
        .iter()
        .find(|snapshot| snapshot.proposal_height > carrier_height)
    {
        return Err(MergeLedgerCommitError::ExecutionBatchInvalid(format!(
            "lane {} relay proposal height {} is after merge carrier height {carrier_height}",
            snapshot.lane_id, snapshot.proposal_height
        )));
    }
    Ok(())
}

fn merge_entry_is_queue_plan_admission_only(entry: &MergeLedgerEntry) -> bool {
    !entry.queue_plan_admissions.is_empty()
        && entry.lane_snapshots.is_empty()
        && entry.execution_batch.is_none()
        && entry.lane_drain_certificates.is_empty()
}

fn merge_candidate_is_queue_plan_admission_only(
    candidate: &crate::merge::MergeLedgerCandidate,
) -> bool {
    !candidate.queue_plan_admissions.is_empty()
        && candidate.lane_snapshots.is_empty()
        && candidate.execution_batch.is_none()
        && candidate.lane_drain_certificates.is_empty()
}

fn merge_effective_empty_global_state_root() -> Hash {
    crate::merge::reduce_merge_hint_roots(&[])
}

fn validate_merge_binding_transition(
    previous: &MergeLedgerEntry,
    current: &MergeLedgerEntry,
) -> Result<(), MergeLedgerCommitError> {
    let previous_by_lane = previous
        .active_lanes
        .iter()
        .map(|binding| (binding.lane_id, binding))
        .collect::<BTreeMap<_, _>>();

    if previous.lane_catalog_hash == current.lane_catalog_hash {
        let same_catalog_shape = previous.active_lanes.len() == current.active_lanes.len()
            && current.active_lanes.iter().all(|binding| {
                previous_by_lane.get(&binding.lane_id).is_some_and(|prior| {
                    prior.dataspace_id == binding.dataspace_id
                        && prior.lane_config_hash == binding.lane_config_hash
                })
            });
        if !same_catalog_shape {
            return Err(MergeLedgerCommitError::IncarnationContext(
                "unchanged catalog hash changed its active lane configuration".to_owned(),
            ));
        }
    }

    for binding in &current.active_lanes {
        let Some(previous_binding) = previous_by_lane.get(&binding.lane_id) else {
            continue;
        };
        if *previous_binding == binding {
            continue;
        }
        if previous_binding.lane_config_hash == binding.lane_config_hash
            && previous_binding.dataspace_id != binding.dataspace_id
        {
            return Err(MergeLedgerCommitError::IncarnationContext(format!(
                "unchanged lane {} changed its dataspace binding",
                binding.lane_id
            )));
        }
        if previous_binding.incarnation == binding.incarnation
            || binding.activation_height <= previous_binding.activation_height
        {
            return Err(MergeLedgerCommitError::IncarnationContext(format!(
                "replacement lane {} must use a fresh incarnation and a later activation",
                binding.lane_id
            )));
        }
    }
    Ok(())
}

/// Full-history guard for live and recovered merge binding transitions.
///
/// The rolling merge-ledger query cache is deliberately bounded, so it cannot
/// be the authority for incarnation reuse checks. This compact index retains
/// every authenticated incarnation and the latest activation per lane while
/// keeping only the immediately previous entry needed for transition checks.
#[derive(Clone, Debug, Default)]
struct MergeBindingHistory {
    latest_entry: Option<MergeLedgerEntry>,
    historical_incarnations: BTreeSet<Hash>,
    latest_activation_by_lane: BTreeMap<LaneId, u64>,
}

impl MergeBindingHistory {
    fn validate_next(&self, entry: &MergeLedgerEntry) -> Result<(), MergeLedgerCommitError> {
        if let Some(previous) = self.latest_entry.as_ref() {
            validate_merge_binding_transition(previous, entry)?;
        }
        for binding in &entry.active_lanes {
            let unchanged = self
                .latest_entry
                .as_ref()
                .is_some_and(|previous| previous.active_lanes.iter().any(|prior| prior == binding));
            if unchanged {
                continue;
            }
            if self.historical_incarnations.contains(&binding.incarnation) {
                return Err(MergeLedgerCommitError::IncarnationContext(format!(
                    "lane {} reuses a historical incarnation commitment",
                    binding.lane_id
                )));
            }
            if self
                .latest_activation_by_lane
                .get(&binding.lane_id)
                .is_some_and(|activation| binding.activation_height <= *activation)
            {
                return Err(MergeLedgerCommitError::IncarnationContext(format!(
                    "lane {} reactivation does not advance its historical activation height",
                    binding.lane_id
                )));
            }
        }
        Ok(())
    }

    fn record(&mut self, entry: &MergeLedgerEntry) {
        for binding in &entry.active_lanes {
            self.historical_incarnations.insert(binding.incarnation);
            self.latest_activation_by_lane
                .entry(binding.lane_id)
                .and_modify(|activation| {
                    *activation = (*activation).max(binding.activation_height);
                })
                .or_insert(binding.activation_height);
        }
        self.latest_entry = Some(entry.clone());
    }

    #[cfg(test)]
    fn from_entries(entries: &[MergeLedgerEntry]) -> Result<Self, MergeLedgerCommitError> {
        let mut history = Self::default();
        for entry in entries {
            history.validate_next(entry)?;
            history.record(entry);
        }
        Ok(history)
    }
}

/// Single authoritative snapshot for all merge-admission progression state.
///
/// Query caches remain separate and bounded, but epoch, incarnation, relay-tip,
/// and autonomous-execution progression must be observed and published as one
/// unit so concurrent validation cannot mix adjacent merge epochs.
#[derive(Clone, Debug, Default)]
struct MergeAdmissionState {
    binding_history: MergeBindingHistory,
    latest_lane_snapshots: BTreeMap<(LaneId, DataSpaceId, Hash), MergeLaneSnapshot>,
    latest_execution_heights: BTreeMap<(LaneId, DataSpaceId, Hash), u64>,
}

#[derive(Clone)]
struct MergeAdmissionSnapshot {
    expected_epoch: u64,
    previous_view: u64,
    previous_global_state_root: Hash,
    latest_lane_snapshots: BTreeMap<(LaneId, DataSpaceId, Hash), MergeLaneSnapshot>,
    latest_execution_heights: BTreeMap<(LaneId, DataSpaceId, Hash), u64>,
}

impl MergeAdmissionSnapshot {
    fn expected_epoch(&self) -> u64 {
        self.expected_epoch
    }

    fn previous_view(&self) -> u64 {
        self.previous_view
    }

    fn previous_global_state_root(&self) -> Hash {
        self.previous_global_state_root
    }
}

impl MergeAdmissionState {
    fn latest_entry(&self) -> Option<&MergeLedgerEntry> {
        self.binding_history.latest_entry.as_ref()
    }

    fn expected_epoch(&self) -> u64 {
        self.latest_entry()
            .map_or(1, |entry| entry.epoch_id.saturating_add(1))
    }

    fn previous_view(&self) -> u64 {
        self.latest_entry().map_or(0, |entry| entry.merge_qc.view)
    }

    fn previous_global_state_root(&self) -> Hash {
        self.latest_entry()
            .map_or_else(merge_effective_empty_global_state_root, |entry| {
                entry.global_state_root
            })
    }

    fn snapshot(&self) -> MergeAdmissionSnapshot {
        MergeAdmissionSnapshot {
            expected_epoch: self.expected_epoch(),
            previous_view: self.previous_view(),
            previous_global_state_root: self.previous_global_state_root(),
            latest_lane_snapshots: self.latest_lane_snapshots.clone(),
            latest_execution_heights: self.latest_execution_heights.clone(),
        }
    }

    fn validate_next(&self, entry: &MergeLedgerEntry) -> Result<(), MergeLedgerCommitError> {
        self.binding_history.validate_next(entry)?;
        let expected_epoch = self.expected_epoch();
        if entry.epoch_id != expected_epoch {
            return Err(MergeLedgerCommitError::NonMonotonicEpoch {
                expected: expected_epoch,
                attempted: entry.epoch_id,
            });
        }
        if merge_entry_is_queue_plan_admission_only(entry)
            && entry.global_state_root != self.previous_global_state_root()
        {
            return Err(MergeLedgerCommitError::MergeQCDigestMismatch {
                expected: self.previous_global_state_root(),
                actual: entry.global_state_root,
            });
        }
        validate_merge_lane_snapshot_progression_against(
            &self.latest_lane_snapshots,
            &entry.lane_snapshots,
        )?;
        if let Some(batch) = entry.execution_batch.as_ref() {
            for execution in &batch.lanes {
                let descriptor = &execution.proposal.descriptor;
                // Relay settlement and Native participant controls can advance the unified
                // WSV frontier between autonomous batches. This cache therefore rejects only
                // autonomous replay/regression; live validation checks exact contiguity and
                // predecessor identity against that WSV frontier, while startup recovery uses
                // its reconstructed durable sequence.
                let latest_height = self
                    .latest_execution_heights
                    .get(&(
                        descriptor.lane_id,
                        descriptor.dataspace_id,
                        descriptor.lane_incarnation,
                    ))
                    .copied();
                if latest_height.is_some_and(|height| descriptor.lane_block_height <= height) {
                    let expected_height = latest_height
                        .and_then(|height| height.checked_add(1))
                        .unwrap_or(u64::MAX);
                    return Err(MergeLedgerCommitError::NonContiguousLaneSnapshot {
                        lane_id: descriptor.lane_id,
                        dataspace_id: descriptor.dataspace_id,
                        expected_height,
                        attempted_height: descriptor.lane_block_height,
                    });
                }
            }
        }
        Ok(())
    }

    fn record(&mut self, entry: &MergeLedgerEntry) {
        self.binding_history.record(entry);
        for snapshot in &entry.lane_snapshots {
            self.latest_lane_snapshots.insert(
                (
                    snapshot.lane_id,
                    snapshot.dataspace_id,
                    snapshot.lane_incarnation,
                ),
                snapshot.clone(),
            );
        }
        if let Some(batch) = entry.execution_batch.as_ref() {
            for execution in &batch.lanes {
                let descriptor = &execution.proposal.descriptor;
                self.latest_execution_heights.insert(
                    (
                        descriptor.lane_id,
                        descriptor.dataspace_id,
                        descriptor.lane_incarnation,
                    ),
                    descriptor.lane_block_height,
                );
            }
        }
    }

    fn from_entries(entries: &[MergeLedgerEntry]) -> Result<Self, MergeLedgerCommitError> {
        let mut admission = Self::default();
        for entry in entries {
            admission.validate_next(entry)?;
            admission.record(entry);
        }
        Ok(admission)
    }

    fn prune_lane_progress(&mut self, lanes: &BTreeSet<LaneId>) {
        self.latest_lane_snapshots
            .retain(|(lane_id, _, _), _| !lanes.contains(lane_id));
        self.latest_execution_heights
            .retain(|(lane_id, _, _), _| !lanes.contains(lane_id));
    }
}

/// Errors surfaced when applying lane lifecycle updates.
#[derive(Debug, ThisError)]
pub enum LaneLifecycleError {
    /// Lane lifecycle updates require Nexus to be enabled.
    #[error("lane lifecycle updates require nexus.enabled=true")]
    NexusDisabled,
    /// Lifecycle plans must add or retire at least one lane.
    #[error("lane lifecycle plan must add or retire at least one lane")]
    EmptyPlan,
    /// A block may carry at most one lane lifecycle transition.
    #[error("a lane lifecycle transition is already staged in this block")]
    LifecycleAlreadyStaged,
    /// The signed transition was prepared against a different lane catalog.
    #[error(
        "lane lifecycle expected catalog hash {expected} does not match current catalog hash {actual}"
    )]
    StaleCatalog {
        /// Catalog commitment signed by the transaction authority.
        expected: Hash,
        /// Catalog commitment observed during deterministic execution.
        actual: Hash,
    },
    /// Runtime configuration attempted to mutate committed lane topology
    /// without an authenticated on-chain lifecycle transition.
    #[error(
        "lane catalog mutation at committed height {height} requires an authenticated lifecycle transition (current {current}, attempted {attempted})"
    )]
    RuntimeCatalogMutationRequiresLifecycle {
        /// Current committed global height.
        height: u64,
        /// Exact current catalog commitment.
        current: Hash,
        /// Exact attempted catalog commitment.
        attempted: Hash,
    },
    /// Startup configuration conflicts with the exact catalog baseline
    /// persisted before the first durable block.
    #[error("configured lane catalog baseline validation failed: {0}")]
    ConfiguredCatalogBaseline(String),
    /// A signed lifecycle transition targeted an older active-incarnation set.
    #[error(
        "lane lifecycle expected incarnation root {expected} does not match current root {actual}"
    )]
    StaleIncarnationRoot {
        /// Incarnation root signed by the transaction authority.
        expected: Hash,
        /// Incarnation root observed during deterministic execution.
        actual: Hash,
    },
    /// A lane with unapplied or unmerged progress cannot be retired or replaced.
    #[error("lane {lane} cannot be retired while {reason}")]
    UnsafeRetirement {
        /// Lane whose lifecycle would end or reset.
        lane: LaneId,
        /// Pending-progress invariant that blocks retirement.
        reason: &'static str,
    },
    /// A dependent Nexus feature was enabled while Nexus itself is disabled.
    #[error("{0} requires nexus.enabled=true")]
    NexusDisabledFeature(&'static str),
    /// Disabled Nexus configuration must not carry multi-lane overrides.
    #[error("nexus.enabled=false requires the default single-lane catalog and routing policy")]
    NexusDisabledWithLaneOverrides,
    /// Relay worker requires asynchronous lane-relay-burn fee settlement.
    #[error("nexus.relay_worker.enabled requires lane-relay-burn fee settlement")]
    RelayWorkerFeeConfig,
    /// Nexus fee asset selector must be the canonical XOR asset or XOR alias.
    #[error(
        "invalid nexus.fees.fee_asset_id; expected XOR canonical asset definition id or xor#universal alias"
    )]
    NexusFeeAssetIdInvalid,
    /// Nexus fee sink account literal must be non-empty.
    #[error("nexus.fees.fee_sink_account_id must not be empty")]
    NexusFeeSinkAccountEmpty,
    /// Lane-relay emergency multisig threshold cannot exceed member count.
    #[error("nexus.lane_relay_emergency.multisig_threshold must be <= multisig_members")]
    LaneRelayEmergencyThreshold,
    /// Dataspace default sponsor programs require Nexus to be enabled.
    #[error("nexus dataspace fee sponsor programs require nexus.enabled=true")]
    DataspaceFeeSponsorProgramsRequireNexusEnabled,
    /// Dataspace default sponsor program references a dataspace absent from the catalog.
    #[error("nexus dataspace fee sponsor program references unknown dataspace {0}")]
    DataspaceFeeSponsorProgramUnknownDataspace(DataSpaceId),
    /// Lifecycle plan references a dataspace that is not present in the catalog.
    #[error("lane lifecycle plan references unknown dataspace {0}")]
    UnknownDataspace(DataSpaceId),
    /// A persisted asset-definition alias still occupies a textual dataspace namespace selected
    /// for retirement.
    #[error(
        "dataspace alias `{dataspace_alias}` cannot be retired while asset definition {asset_definition_id} retains alias `{asset_alias}`; clear the asset-definition alias binding first"
    )]
    AssetDefinitionAliasNamespaceInUse {
        /// Textual dataspace alias removed by the attempted catalog.
        dataspace_alias: String,
        /// Definition retaining the blocking alias binding.
        asset_definition_id: AssetDefinitionId,
        /// Exact persisted alias which must be cleared first.
        asset_alias: AssetDefinitionAlias,
    },
    /// External lane configuration attempted to claim an autoscale-managed lane.
    #[error("lane {0} uses reserved autoscale metadata")]
    ReservedAutoscaleManagedLane(LaneId),
    /// External lane configuration attempted to occupy an autoscale elastic lane id.
    #[error(
        "manual lane {lane} is inside reserved autoscale elastic lane id range [{min_lanes}, {max_lanes})"
    )]
    ReservedAutoscaleElasticLaneId {
        /// Manual lane id inside the autoscale elastic range.
        lane: LaneId,
        /// Inclusive lower bound for autoscale elastic lane ids.
        min_lanes: u32,
        /// Exclusive upper bound for autoscale elastic lane ids.
        max_lanes: u32,
    },
    /// Autoscale-managed lane id is outside the configured autoscale id range.
    #[error(
        "autoscale-managed lane {lane} is outside configured autoscale lane id range [{min_lanes}, {max_lanes})"
    )]
    AutoscaleManagedLaneOutOfBounds {
        /// Lane id carrying autoscale-managed metadata.
        lane: LaneId,
        /// Inclusive lower bound for autoscale-managed lane ids.
        min_lanes: u32,
        /// Exclusive upper bound for autoscale-managed lane ids.
        max_lanes: u32,
    },
    /// Autoscale lane bounds are empty or inverted in runtime state.
    #[error("nexus.autoscale.min_lanes {min_lanes} must be < max_lanes {max_lanes}")]
    AutoscaleInvalidLaneBounds {
        /// Inclusive lower lane-id bound of the autoscale-owned range.
        min_lanes: u32,
        /// Exclusive upper lane-id bound of the autoscale-owned range.
        max_lanes: u32,
    },
    /// Autoscale exclusive upper lane-id bound exceeds the compiled deterministic safety cap.
    #[error("nexus.autoscale.max_lanes {max_lanes} exceeds compiled safety cap {cap}")]
    AutoscaleMaxLanesExceedsCap {
        /// Exclusive upper lane-id bound of the autoscale-owned range.
        max_lanes: u32,
        /// Compiled maximum supported exclusive lane-id bound.
        cap: u32,
    },
    /// The default route must be a base lane below the autoscale-owned elastic id range.
    #[error(
        "nexus.routing_policy.default_lane {lane} must be below nexus.autoscale.min_lanes {min_lanes} when autoscale is enabled"
    )]
    AutoscaleDefaultLaneNotBase {
        /// Default lane id at or above the autoscale elastic range.
        lane: LaneId,
        /// Inclusive lower bound for autoscale elastic lane ids.
        min_lanes: u32,
    },
    /// The autoscale routing base depends on lane-specific policy that cannot be cloned safely.
    #[error("nexus autoscale base lane {lane} is not self-contained: {reason}")]
    AutoscaleBaseProfileUnsupported {
        /// Routing default lane used as the elastic profile template.
        lane: LaneId,
        /// Static policy dependency that prevents deterministic autonomous cloning.
        reason: &'static str,
    },
    /// Compliance is enabled but an added lane lacks an exact loaded policy.
    #[error(
        "lane {lane} cannot become active while compliance is enabled without an exact loaded policy"
    )]
    CompliancePolicyUnavailable {
        /// Prospective lane missing a policy binding.
        lane: LaneId,
    },
    /// The frozen manifest source set cannot enforce a prospective active lane.
    #[error("lane {lane} cannot become active under the installed manifest policy: {reason}")]
    ManifestPolicyUnavailable {
        /// Prospective lane without an enforceable frozen manifest binding.
        lane: LaneId,
        /// Deterministic manifest coverage failure.
        reason: String,
    },
    /// Autoscale-managed lane cannot be preserved or created while autoscale is disabled.
    #[error("autoscale-managed lane {0} requires nexus.autoscale.enabled=true")]
    AutoscaleManagedLaneDisabled(LaneId),
    /// Autoscale-managed lane is outside the default dataspace owned by the autoscaler.
    #[error(
        "autoscale-managed lane {lane} is bound to dataspace {dataspace}, but autoscale owns only default dataspace {default_dataspace}"
    )]
    AutoscaleManagedLaneWrongDataspace {
        /// Lane id carrying autoscale-managed metadata.
        lane: LaneId,
        /// Dataspace bound to the autoscale-managed lane.
        dataspace: DataSpaceId,
        /// Configured default dataspace that the autoscaler owns.
        default_dataspace: DataSpaceId,
    },
    /// Autoscale-managed lane has malformed deterministic ownership metadata.
    #[error("autoscale-managed lane {lane} is invalid: {reason}")]
    InvalidAutoscaleManagedLane {
        /// Lane id carrying malformed autoscale-managed metadata.
        lane: LaneId,
        /// Static validation reason.
        reason: &'static str,
    },
    /// Internal autoscale lifecycle attempted to add a lane it does not own.
    #[error("internal autoscale lifecycle cannot add unmanaged lane {0}")]
    AutoscaleAddUnmanagedLane(LaneId),
    /// Internal autoscale lifecycle attempted to retire a lane it does not own.
    #[error("internal autoscale lifecycle cannot retire unmanaged lane {0}")]
    AutoscaleRetireUnmanagedLane(LaneId),
    /// Internal autoscale transition metadata does not match the lifecycle plan.
    #[error("internal autoscale {transition} transition plan mismatch: {reason}")]
    AutoscaleTransitionPlanMismatch {
        /// Transition direction being applied.
        transition: &'static str,
        /// Static validation reason.
        reason: &'static str,
    },
    /// The prospective autoscale lane has no valid exact `3f+1` committee size.
    #[error(
        "autoscale-managed lane {lane} in dataspace {dataspace} cannot derive an exact 3f+1 committee within the validator cap"
    )]
    AutoscaleCommitteeSizeInvalid {
        /// Prospective autoscale-managed lane.
        lane: LaneId,
        /// Dataspace whose fault-tolerance policy determines committee size.
        dataspace: DataSpaceId,
    },
    /// The prospective autoscale lane has too few distinct live authoritative peers.
    #[error(
        "autoscale-managed lane {lane} in dataspace {dataspace} requires {required} live authoritative peers, but resolved {actual}"
    )]
    AutoscaleCommitteeUnavailable {
        /// Prospective autoscale-managed lane.
        lane: LaneId,
        /// Dataspace whose authority was resolved.
        dataspace: DataSpaceId,
        /// Exact `3f+1` committee size required by dataspace policy.
        required: usize,
        /// Number of distinct live authoritative peers selected by the resolver.
        actual: usize,
    },
    /// The transition height has no representable following proposal height.
    #[error("autoscale-managed lane {0} cannot be created at the maximum block height")]
    AutoscaleProposalHeightOverflow(LaneId),
    /// Active lane incarnation commitments are missing, stale, or malformed.
    #[error("invalid lane incarnation state: {0}")]
    LaneIncarnationState(String),
    /// Lifecycle plan attempted to destroy and recreate the active default route lane.
    #[error("lane lifecycle plan cannot replace routing default lane {0}")]
    DefaultLaneReplacement(LaneId),
    /// Lifecycle plan attempted to retire or replace Kura's physical primary lane.
    #[error("lane lifecycle plan cannot retire or replace physical primary lane 0")]
    PhysicalPrimaryReplacement,
    /// Lifecycle plan would leave routing policy targets unresolved.
    #[error("lane lifecycle plan leaves routing policy unresolved: {0}")]
    RoutingPolicy(String),
    /// Invalid lifecycle plan or catalog transition.
    #[error("failed to apply lane lifecycle plan: {0}")]
    Catalog(#[from] iroha_data_model::nexus::LaneCatalogError),
    /// Storage or shard/topology reconciliation failed while applying the lifecycle update.
    #[error("failed to reconcile lane storage: {0}")]
    Storage(String),
}

/// Errors surfaced while installing runtime ZK configuration into committed state.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ThisError)]
pub enum ZkConfigInstallError {
    /// Consensus-accounted pending usage has an impossible counter combination.
    #[error("committed SCCP pending outbound usage is structurally invalid: {usage:?}")]
    InvalidSccpPendingUsage {
        /// Persisted usage observed at the configuration boundary.
        usage: SccpOutboundPendingUsageV1,
    },
    /// A pending outbound record does not carry a nonempty payload length that
    /// can be represented by the consensus usage counters.
    #[error("committed SCCP pending outbound state contains an invalid payload length")]
    InvalidSccpPendingPayloadLength,
    /// Recomputing pending outbound usage from payload-bearing records
    /// overflowed its fixed-width consensus counters.
    #[error(
        "committed SCCP pending outbound usage overflows while recomputing payload-bearing state"
    )]
    SccpPendingUsageOverflow,
    /// The persisted usage cell does not exactly describe the payload-bearing
    /// pending outbound map.
    #[error(
        "committed SCCP pending outbound usage differs from payload-bearing state: expected {expected:?}, found {usage:?}"
    )]
    SccpPendingUsageMismatch {
        /// Persisted usage observed at the configuration boundary.
        usage: SccpOutboundPendingUsageV1,
        /// Usage recomputed from every pending payload-bearing record.
        expected: SccpOutboundPendingUsageV1,
    },
    /// Candidate pending-outbox caps are below already committed usage.
    #[error(
        "committed SCCP pending outbound usage exceeds configured limits: usage={usage:?}, maxima messages={max_messages} bytes={max_payload_bytes}"
    )]
    SccpPendingUsageLimitExceeded {
        /// Persisted usage observed at the configuration boundary.
        usage: SccpOutboundPendingUsageV1,
        /// Candidate maximum number of payload-bearing pending messages.
        max_messages: NonZeroU64,
        /// Candidate maximum aggregate pending payload bytes.
        max_payload_bytes: NonZeroU64,
    },
}

struct LaneGeometryCatalogPublicationFailure {
    error: LaneLifecycleError,
    rollback_safe: bool,
}

/// Errors surfaced while rebuilding DA indexes from the committed block log.
#[derive(Copy, Clone, Debug, ThisError, PartialEq, Eq)]
pub(crate) enum DaIndexHydrationError {
    /// DA shard cursor replay failed.
    #[error("DA shard cursor hydration failed: {0}")]
    ShardCursor(#[from] DaShardCursorError),
    /// DA receipt cursor replay failed.
    #[error("DA receipt cursor hydration failed: {0}")]
    ReceiptCursor(#[from] DaReceiptCursorError),
}

/// Errors surfaced when computing block inclusion/execution proofs.
#[derive(Copy, Clone, Debug, ThisError)]
pub enum BlockProofError {
    /// Height must be non-zero.
    #[error("block height must be at least 1")]
    ZeroHeight,
    /// Height exceeds usize conversion on the current platform.
    #[error("block height {0} exceeds host pointer width")]
    HeightOutOfRange(NonZeroU64),
    /// Referenced block not found in storage.
    #[error("block {0} not found in Kura")]
    BlockNotFound(NonZeroU64),
    /// The durable Kura slot contains a block with a different header height.
    #[error("Kura slot {requested} contains block header height {actual}")]
    BlockHeightMismatch {
        /// Height requested from the durable index.
        requested: NonZeroU64,
        /// Height declared by the decoded block header.
        actual: NonZeroU64,
    },
    /// Block does not have entrypoint results attached.
    #[error("block {0} is missing execution results")]
    MissingResults(NonZeroU64),
    /// Target entrypoint not present in the block.
    #[error("entrypoint hash {entry_hash:?} not found in block {block_height}")]
    EntrypointNotFound {
        /// Entrypoint hash requested by the caller.
        entry_hash: HashOf<TransactionEntrypoint>,
        /// Height for which the lookup was performed.
        block_height: NonZeroU64,
    },
    /// Execution result is not available for the given entrypoint.
    #[error("execution result missing for entrypoint {entry_hash:?} in block {block_height}")]
    ExecutionResultMissing {
        /// Entrypoint hash requested by the caller.
        entry_hash: HashOf<TransactionEntrypoint>,
        /// Height for which the lookup was performed.
        block_height: NonZeroU64,
    },
    /// Merkle proof could not be constructed for the entrypoint.
    #[error("merkle proof unavailable for entrypoint {entry_hash:?} in block {block_height}")]
    MerkleProofUnavailable {
        /// Entrypoint hash requested by the caller.
        entry_hash: HashOf<TransactionEntrypoint>,
        /// Height for which the lookup was performed.
        block_height: NonZeroU64,
    },
    /// The canonical executed block wire identity could not be derived.
    #[error("executed block wire hash unavailable for block {0}")]
    ExecutedBlockWireHashUnavailable(NonZeroU64),
}

/// Key identifying a directly applied standalone lane block in world state.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Encode, Decode)]
pub struct DirectLaneBlockApplicationKey {
    /// Lane that produced the directly applied block.
    pub lane_id: LaneId,
    /// Incarnation that owns the lane-local height namespace.
    pub lane_incarnation: Hash,
    /// Lane-local block height.
    pub lane_block_height: u64,
}

impl mv::json::JsonKeyCodec for DirectLaneBlockApplicationKey {
    fn encode_json_key(&self, out: &mut String) {
        let key = format!(
            "{}:{}:{}",
            self.lane_id.as_u32(),
            hex::encode(self.lane_incarnation.as_ref()),
            self.lane_block_height
        );
        json::write_json_string(&key, out);
    }

    fn decode_json_key(encoded: &str) -> Result<Self, json::Error> {
        let mut parts = encoded.split(':');
        let lane_id = parts.next().ok_or_else(|| {
            json::Error::Message("expected direct lane application key lane id".into())
        })?;
        let lane_incarnation = parts.next().ok_or_else(|| {
            json::Error::Message("expected direct lane application key incarnation".into())
        })?;
        let lane_block_height = parts.next().ok_or_else(|| {
            json::Error::Message("expected direct lane application key block height".into())
        })?;
        if parts.next().is_some() {
            return Err(json::Error::Message(
                "direct lane application key has trailing components".into(),
            ));
        }
        let lane_id = lane_id.parse::<u32>().map_err(|err| {
            json::Error::Message(format!("invalid direct lane application lane id: {err}"))
        })?;
        let lane_block_height = lane_block_height.parse::<u64>().map_err(|err| {
            json::Error::Message(format!(
                "invalid direct lane application block height: {err}"
            ))
        })?;
        let lane_incarnation = hex::decode(lane_incarnation).map_err(|err| {
            json::Error::Message(format!(
                "invalid direct lane application incarnation: {err}"
            ))
        })?;
        let lane_incarnation: [u8; Hash::LENGTH] =
            lane_incarnation.try_into().map_err(|bytes: Vec<u8>| {
                json::Error::Message(format!(
                    "invalid direct lane application incarnation length: expected {}, got {}",
                    Hash::LENGTH,
                    bytes.len()
                ))
            })?;
        let lane_incarnation = Hash::prehashed(lane_incarnation);
        if lane_incarnation_is_zero(lane_incarnation) {
            return Err(json::Error::Message(
                "direct lane application incarnation must be non-zero".into(),
            ));
        }
        Ok(Self {
            lane_id: LaneId::new(lane_id),
            lane_incarnation,
            lane_block_height,
        })
    }
}

/// World-state marker committed atomically with direct standalone lane-block effects.
#[derive(
    Debug, Clone, PartialEq, Eq, NoritoSerialize, NoritoDeserialize, JsonSerialize, JsonDeserialize,
)]
pub struct DirectLaneBlockApplicationMarker {
    /// Lane that produced the directly applied block.
    pub lane_id: LaneId,
    /// Incarnation that owns the lane-local height namespace.
    pub lane_incarnation: Hash,
    /// Global proposal height that planned this lane-local block.
    pub proposal_height: u64,
    /// Dataspace routed by the directly applied block.
    pub dataspace_id: DataSpaceId,
    /// Lane-local block height.
    pub lane_block_height: u64,
    /// Descriptor hash certified by the lane-block proposal.
    pub descriptor_hash: Hash,
    /// Proposal hash certified by the lane-block quorum certificates.
    pub proposal_hash: Hash,
    /// Committed world-state height used as the direct-execution base.
    pub preflight_state_height: u64,
    /// Committed world-state hash used as the direct-execution base.
    pub preflight_state_hash: HashOf<BlockHeader>,
    /// Hashes of committed transaction results in lane descriptor order.
    pub result_hashes: Vec<Hash>,
}

impl DirectLaneBlockApplicationMarker {
    pub(crate) fn from_direct_receipt(
        receipt: &crate::kura::LaneBlockApplicationReceiptArtifact,
    ) -> Option<Self> {
        if receipt.format != crate::kura::LaneBlockApplicationReceiptArtifactFormat::DirectExecution
        {
            return None;
        }
        Some(Self {
            lane_id: receipt.proposal.descriptor.lane_id,
            lane_incarnation: receipt.proposal.descriptor.lane_incarnation,
            proposal_height: receipt.proposal.descriptor.proposal_height,
            dataspace_id: receipt.proposal.descriptor.dataspace_id,
            lane_block_height: receipt.proposal.descriptor.lane_block_height,
            descriptor_hash: receipt.proposal.descriptor.descriptor_hash,
            proposal_hash: receipt.proposal.proposal_hash,
            preflight_state_height: receipt.application_block_height,
            preflight_state_hash: receipt.application_block_hash,
            result_hashes: receipt.result_hashes.clone(),
        })
    }

    pub(crate) fn key(&self) -> DirectLaneBlockApplicationKey {
        DirectLaneBlockApplicationKey {
            lane_id: self.lane_id,
            lane_incarnation: self.lane_incarnation,
            lane_block_height: self.lane_block_height,
        }
    }
}

/// Consensus key identifying one authority-owned pending contract-code upload.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Encode, Decode)]
pub struct SmartContractCodeUploadKey {
    /// Account that owns and may finalize or cancel the upload.
    pub authority: AccountId,
    /// Declared hash of the complete contract artifact.
    pub code_hash: Hash,
}

impl SmartContractCodeUploadKey {
    /// Construct an upload key from its owner and artifact hash.
    #[must_use]
    pub fn new(authority: AccountId, code_hash: Hash) -> Self {
        Self {
            authority,
            code_hash,
        }
    }

    pub(crate) fn authority_range(authority: &AccountId) -> std::ops::RangeInclusive<Self> {
        Self::new(authority.clone(), Hash::prehashed([0; Hash::LENGTH]))
            ..=Self::new(authority.clone(), Hash::prehashed([u8::MAX; Hash::LENGTH]))
    }
}

impl mv::json::JsonKeyCodec for SmartContractCodeUploadKey {
    fn encode_json_key(&self, out: &mut String) {
        let key = format!(
            "{}|{}",
            self.authority,
            hex::encode(self.code_hash.as_ref())
        );
        json::write_json_string(&key, out);
    }

    fn decode_json_key(encoded: &str) -> Result<Self, json::Error> {
        let mut parts = encoded.split('|');
        let authority = parts
            .next()
            .ok_or_else(|| json::Error::Message("expected contract upload key authority".into()))?;
        let code_hash = parts
            .next()
            .ok_or_else(|| json::Error::Message("expected contract upload key code hash".into()))?;
        if parts.next().is_some() {
            return Err(json::Error::Message(
                "contract upload key has trailing components".into(),
            ));
        }
        let authority = AccountId::parse_encoded(authority)
            .map(iroha_data_model::account::ParsedAccountId::into_account_id)
            .map_err(|error| {
                json::Error::Message(format!("invalid contract upload key authority: {error}"))
            })?;
        let code_hash = decode_contract_upload_key_hash(code_hash)?;
        Ok(Self {
            authority,
            code_hash,
        })
    }
}

fn decode_contract_upload_key_hash(encoded: &str) -> Result<Hash, json::Error> {
    let bytes = hex::decode(encoded).map_err(|error| {
        json::Error::Message(format!("invalid contract upload key hash: {error}"))
    })?;
    let bytes: [u8; Hash::LENGTH] = bytes.try_into().map_err(|bytes: Vec<u8>| {
        json::Error::Message(format!(
            "invalid contract upload key hash length: expected {}, got {}",
            Hash::LENGTH,
            bytes.len()
        ))
    })?;
    Ok(Hash::prehashed(bytes))
}

/// Consensus key identifying one chunk within an authority-owned pending upload.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Encode, Decode)]
pub struct SmartContractCodeUploadChunkKey {
    /// Pending upload that owns the chunk.
    pub upload: SmartContractCodeUploadKey,
    /// Zero-based chunk position.
    pub chunk_index: u32,
}

impl SmartContractCodeUploadChunkKey {
    /// Construct a pending-upload chunk key.
    #[must_use]
    pub fn new(upload: SmartContractCodeUploadKey, chunk_index: u32) -> Self {
        Self {
            upload,
            chunk_index,
        }
    }

    pub(crate) fn upload_range(
        upload: &SmartContractCodeUploadKey,
    ) -> std::ops::RangeInclusive<Self> {
        Self::new(upload.clone(), 0)..=Self::new(upload.clone(), u32::MAX)
    }
}

impl mv::json::JsonKeyCodec for SmartContractCodeUploadChunkKey {
    fn encode_json_key(&self, out: &mut String) {
        let key = format!(
            "{}|{}|{}",
            self.upload.authority,
            hex::encode(self.upload.code_hash.as_ref()),
            self.chunk_index
        );
        json::write_json_string(&key, out);
    }

    fn decode_json_key(encoded: &str) -> Result<Self, json::Error> {
        let mut parts = encoded.split('|');
        let authority = parts.next().ok_or_else(|| {
            json::Error::Message("expected contract upload chunk key authority".into())
        })?;
        let code_hash = parts.next().ok_or_else(|| {
            json::Error::Message("expected contract upload chunk key code hash".into())
        })?;
        let chunk_index = parts.next().ok_or_else(|| {
            json::Error::Message("expected contract upload chunk key index".into())
        })?;
        if parts.next().is_some() {
            return Err(json::Error::Message(
                "contract upload chunk key has trailing components".into(),
            ));
        }
        let authority = AccountId::parse_encoded(authority)
            .map(iroha_data_model::account::ParsedAccountId::into_account_id)
            .map_err(|error| {
                json::Error::Message(format!(
                    "invalid contract upload chunk key authority: {error}"
                ))
            })?;
        let code_hash = decode_contract_upload_key_hash(code_hash)?;
        let chunk_index = chunk_index.parse::<u32>().map_err(|error| {
            json::Error::Message(format!("invalid contract upload chunk key index: {error}"))
        })?;
        Ok(Self {
            upload: SmartContractCodeUploadKey {
                authority,
                code_hash,
            },
            chunk_index,
        })
    }
}

/// Immutable shape descriptor for a pending contract-code upload.
#[derive(
    Debug,
    Clone,
    Copy,
    PartialEq,
    Eq,
    NoritoSerialize,
    NoritoDeserialize,
    JsonSerialize,
    JsonDeserialize,
)]
pub struct SmartContractCodeUploadDescriptor {
    /// Declared byte length of the complete artifact.
    pub total_size: u64,
    /// Exact number of 64 KiB chunks required for the artifact.
    pub chunk_count: u32,
}

/// Read-only progress for one authority-owned pending contract-code upload.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SmartContractCodeUploadProgress {
    /// Immutable shape descriptor supplied by the first accepted chunk.
    pub descriptor: SmartContractCodeUploadDescriptor,
    /// Number of distinct chunks currently stored.
    pub received_chunks: u32,
}

/// Non-zero universal Musubi resolver-index revision persisted in world state.
#[derive(
    Debug,
    Clone,
    Copy,
    PartialEq,
    Eq,
    PartialOrd,
    Ord,
    NoritoSerialize,
    NoritoDeserialize,
    JsonSerialize,
    JsonDeserialize,
)]
#[repr(transparent)]
pub struct MusubiResolverIndexRevisionV1(u64);

impl MusubiResolverIndexRevisionV1 {
    /// Construct a non-zero resolver-index revision.
    pub fn new(revision: u64) -> Result<Self, ParseError> {
        if revision == 0 {
            return Err(ParseError::new(
                "Musubi resolver-index revision must be non-zero",
            ));
        }
        Ok(Self(revision))
    }

    /// Return the exact revision value bound into finalized cursors.
    #[must_use]
    pub const fn get(self) -> u64 {
        self.0
    }

    /// Return the following revision, failing closed on overflow.
    pub fn checked_next(self) -> Option<Self> {
        self.0.checked_add(1).map(Self)
    }
}

impl Default for MusubiResolverIndexRevisionV1 {
    fn default() -> Self {
        Self(1)
    }
}

