#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct LaneIncarnationLineage {
    pub(crate) generation: u64,
    pub(crate) incarnation: Hash,
    pub(crate) activation_height: u64,
}

struct ConfiguredPrimaryReplayGeometry {
    catalog: LaneCatalog,
    lane_config: iroha_config::parameters::actual::LaneConfig,
    incarnations: BTreeMap<LaneId, Hash>,
    activation_heights: BTreeMap<LaneId, u64>,
    lineage: BTreeMap<LaneId, LaneIncarnationLineage>,
    primary_incarnation: Hash,
}

const STATIC_LANE_INCARNATION_DOMAIN: &[u8] = b"iroha:nexus:lane-incarnation:static:v1\0";
const CONFIG_LANE_INCARNATION_DOMAIN: &[u8] = b"iroha:nexus:lane-incarnation:config:v1\0";
const LIFECYCLE_LANE_INCARNATION_DOMAIN: &[u8] = b"iroha:nexus:lane-incarnation:lifecycle:v1\0";
const LANE_INCARNATION_LINEAGE_ROOT_DOMAIN: &[u8] =
    b"iroha:nexus:lane-incarnation-lineage-root:v1\0";

pub(crate) fn lane_incarnation_lineage_root(
    chain_id: &iroha_data_model::ChainId,
    lineage: &BTreeMap<LaneId, LaneIncarnationLineage>,
) -> Hash {
    let entries = lineage
        .iter()
        .map(|(&lane_id, entry)| {
            (
                lane_id,
                entry.generation,
                entry.incarnation,
                entry.activation_height,
            )
        })
        .collect::<Vec<_>>();
    let encoded = (chain_id.clone(), entries).encode();
    Hash::new_from_chunks(&[LANE_INCARNATION_LINEAGE_ROOT_DOMAIN, encoded.as_slice()])
}
#[cfg(test)]
const SYNTHETIC_LANE_LIFECYCLE_HEADER_DOMAIN: &[u8] =
    b"iroha:nexus:lane-incarnation:synthetic-header:v1\0";

fn lane_incarnation_is_zero(incarnation: Hash) -> bool {
    incarnation.as_ref().iter().all(|byte| *byte == 0)
}

fn lane_incarnation_matches_at_height(
    incarnations: &BTreeMap<LaneId, Hash>,
    activation_heights: &BTreeMap<LaneId, u64>,
    lane_id: LaneId,
    proposal_height: u64,
    actual: Hash,
) -> bool {
    incarnations.get(&lane_id) == Some(&actual)
        && activation_heights
            .get(&lane_id)
            .is_some_and(|activation_height| proposal_height > *activation_height)
}

#[cfg(test)]
fn synthetic_lane_lifecycle_header_hash(
    chain_id: &iroha_data_model::ChainId,
    current_block_height: u64,
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
) -> HashOf<BlockHeader> {
    let encoded = (chain_id.clone(), current_block_height, plan.clone()).encode();
    HashOf::from_untyped_unchecked(Hash::new_from_chunks(&[
        SYNTHETIC_LANE_LIFECYCLE_HEADER_DOMAIN,
        encoded.as_slice(),
    ]))
}

fn derive_static_lane_incarnations(
    chain_id: &iroha_data_model::ChainId,
    catalog: &LaneCatalog,
) -> BTreeMap<LaneId, Hash> {
    let catalog_hash = merge_lane_catalog_hash(catalog);
    catalog
        .lanes()
        .iter()
        .map(|lane| {
            let encoded = (
                chain_id.clone(),
                catalog_hash,
                lane.id,
                lane_without_autoscale_drain_metadata(lane),
            )
                .encode();
            (
                lane.id,
                Hash::new_from_chunks(&[STATIC_LANE_INCARNATION_DOMAIN, encoded.as_slice()]),
            )
        })
        .collect()
}

fn configured_primary_replay_geometry(
    chain_id: &iroha_data_model::ChainId,
    configured_lane_catalog: &LaneCatalog,
) -> Result<ConfiguredPrimaryReplayGeometry, LaneLifecycleError> {
    let primary = configured_lane_catalog
        .lanes()
        .first()
        .cloned()
        .ok_or_else(|| {
            LaneLifecycleError::ConfiguredCatalogBaseline(
                "configured lane catalog has no primary lane".to_owned(),
            )
        })?;
    let catalog = LaneCatalog::new(configured_lane_catalog.lane_count(), vec![primary])
        .map_err(|error| LaneLifecycleError::ConfiguredCatalogBaseline(error.to_string()))?;
    let incarnations = derive_static_lane_incarnations(chain_id, &catalog);
    let primary_incarnation = incarnations.get(&LaneId::SINGLE).copied().ok_or_else(|| {
        LaneLifecycleError::ConfiguredCatalogBaseline(
            "configured primary catalog does not contain lane zero".to_owned(),
        )
    })?;
    let activation_heights = BTreeMap::from([(LaneId::SINGLE, 0)]);
    let lineage = BTreeMap::from([(
        LaneId::SINGLE,
        LaneIncarnationLineage {
            generation: 0,
            incarnation: primary_incarnation,
            activation_height: 0,
        },
    )]);
    let lane_config = iroha_config::parameters::actual::LaneConfig::from_catalog(&catalog);
    Ok(ConfiguredPrimaryReplayGeometry {
        catalog,
        lane_config,
        incarnations,
        activation_heights,
        lineage,
        primary_incarnation,
    })
}

fn validate_lane_incarnation_map(
    catalog: &LaneCatalog,
    incarnations: &BTreeMap<LaneId, Hash>,
) -> Result<(), LaneLifecycleError> {
    let expected: BTreeSet<_> = catalog.lanes().iter().map(|lane| lane.id).collect();
    let actual: BTreeSet<_> = incarnations.keys().copied().collect();
    if expected != actual {
        return Err(LaneLifecycleError::LaneIncarnationState(format!(
            "active lane ids {expected:?} do not match incarnation ids {actual:?}"
        )));
    }
    if let Some(lane) = incarnations
        .iter()
        .find_map(|(lane, incarnation)| lane_incarnation_is_zero(*incarnation).then_some(*lane))
    {
        return Err(LaneLifecycleError::LaneIncarnationState(format!(
            "lane {lane} has an all-zero incarnation commitment"
        )));
    }
    let mut unique = BTreeSet::new();
    if let Some((lane, _)) = incarnations
        .iter()
        .find(|(_, incarnation)| !unique.insert(**incarnation))
    {
        return Err(LaneLifecycleError::LaneIncarnationState(format!(
            "lane {lane} reuses another active lane's incarnation commitment"
        )));
    }
    Ok(())
}

fn validate_lane_incarnation_lineage(
    catalog: &LaneCatalog,
    active_incarnations: &BTreeMap<LaneId, Hash>,
    active_activation_heights: &BTreeMap<LaneId, u64>,
    lineage: &BTreeMap<LaneId, LaneIncarnationLineage>,
) -> Result<(), LaneLifecycleError> {
    validate_lane_incarnation_map(catalog, active_incarnations)?;
    validate_lane_incarnation_activation_heights(catalog, active_activation_heights)?;
    let mut unique = BTreeSet::new();
    for (&lane_id, entry) in lineage {
        if lane_incarnation_is_zero(entry.incarnation) {
            return Err(LaneLifecycleError::LaneIncarnationState(format!(
                "retained lineage lane {lane_id} has an all-zero incarnation commitment"
            )));
        }
        if !unique.insert(entry.incarnation) {
            return Err(LaneLifecycleError::LaneIncarnationState(format!(
                "retained lineage lane {lane_id} reuses another lane's latest incarnation commitment"
            )));
        }
    }
    for (&lane_id, &incarnation) in active_incarnations {
        let Some(entry) = lineage.get(&lane_id) else {
            return Err(LaneLifecycleError::LaneIncarnationState(format!(
                "active lane {lane_id} is missing its retained incarnation lineage"
            )));
        };
        if entry.incarnation != incarnation
            || active_activation_heights.get(&lane_id) != Some(&entry.activation_height)
        {
            return Err(LaneLifecycleError::LaneIncarnationState(format!(
                "active lane {lane_id} incarnation or activation does not match its retained lineage"
            )));
        }
    }
    Ok(())
}

fn derive_config_lane_incarnation(
    chain_id: &iroha_data_model::ChainId,
    previous_catalog: &LaneCatalog,
    current_block_height: u64,
    lane: &iroha_data_model::nexus::LaneConfig,
    prior: LaneIncarnationLineage,
    next_generation: u64,
    updated_catalog_hash: Hash,
) -> Hash {
    let previous_catalog_hash =
        iroha_data_model::nexus::LaneLifecycleParameterV1::catalog_hash(previous_catalog);
    let encoded = (
        chain_id.clone(),
        previous_catalog_hash,
        updated_catalog_hash,
        current_block_height,
        lane.id,
        lane.clone(),
        prior.generation,
        prior.incarnation,
        prior.activation_height,
        next_generation,
    )
        .encode();
    Hash::new_from_chunks(&[CONFIG_LANE_INCARNATION_DOMAIN, encoded.as_slice()])
}

fn validate_lane_incarnation_activation_heights(
    catalog: &LaneCatalog,
    activation_heights: &BTreeMap<LaneId, u64>,
) -> Result<(), LaneLifecycleError> {
    let expected: BTreeSet<_> = catalog.lanes().iter().map(|lane| lane.id).collect();
    let actual: BTreeSet<_> = activation_heights.keys().copied().collect();
    if expected != actual {
        return Err(LaneLifecycleError::LaneIncarnationState(format!(
            "active lane ids {expected:?} do not match incarnation activation ids {actual:?}"
        )));
    }
    Ok(())
}

fn derive_lifecycle_lane_incarnation_activation_heights(
    previous_catalog: &LaneCatalog,
    updated_catalog: &LaneCatalog,
    previous: &BTreeMap<LaneId, u64>,
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
    committing_height: u64,
) -> Result<BTreeMap<LaneId, u64>, LaneLifecycleError> {
    validate_lane_incarnation_activation_heights(previous_catalog, previous)?;
    let additions: BTreeSet<_> = plan.additions.iter().map(|lane| lane.id).collect();
    let updated = updated_catalog
        .lanes()
        .iter()
        .map(|lane| {
            let activation_height = if additions.contains(&lane.id) {
                committing_height
            } else {
                previous.get(&lane.id).copied().ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "unchanged lane {} is missing its activation height",
                        lane.id
                    ))
                })?
            };
            Ok((lane.id, activation_height))
        })
        .collect::<Result<BTreeMap<_, _>, LaneLifecycleError>>()?;
    validate_lane_incarnation_activation_heights(updated_catalog, &updated)?;
    Ok(updated)
}

fn lane_lifecycle_incarnation_root(
    catalog: &LaneCatalog,
    incarnations: &BTreeMap<LaneId, Hash>,
) -> Result<Hash, LaneLifecycleError> {
    let entries = iroha_data_model::nexus::LaneLifecycleParameterV1::canonical_incarnations(
        catalog,
        incarnations,
    )
    .map_err(|err| LaneLifecycleError::LaneIncarnationState(err.to_string()))?;
    Ok(iroha_data_model::nexus::LaneLifecycleParameterV1::incarnation_root(&entries))
}

fn derive_lifecycle_lane_incarnations(
    chain_id: &iroha_data_model::ChainId,
    committing_header_hash: HashOf<BlockHeader>,
    previous_catalog: &LaneCatalog,
    updated_catalog: &LaneCatalog,
    previous_incarnations: &BTreeMap<LaneId, Hash>,
    previous_activation_heights: &BTreeMap<LaneId, u64>,
    previous_lineage: &BTreeMap<LaneId, LaneIncarnationLineage>,
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
) -> Result<BTreeMap<LaneId, Hash>, LaneLifecycleError> {
    validate_lane_incarnation_lineage(
        previous_catalog,
        previous_incarnations,
        previous_activation_heights,
        previous_lineage,
    )?;
    let changed_lanes: BTreeSet<_> = plan.additions.iter().map(|lane| lane.id).collect();
    let previous_catalog_hash =
        iroha_data_model::nexus::LaneLifecycleParameterV1::catalog_hash(previous_catalog);
    let mut updated = BTreeMap::new();
    for lane in updated_catalog.lanes() {
        let incarnation = if changed_lanes.contains(&lane.id) {
            let prior = previous_lineage.get(&lane.id).copied();
            let prior_present = [u8::from(prior.is_some())];
            let prior = prior.unwrap_or(LaneIncarnationLineage {
                generation: 0,
                incarnation: Hash::prehashed([0; Hash::LENGTH]),
                activation_height: 0,
            });
            let next_generation = if prior_present[0] == 0 {
                0
            } else {
                prior.generation.checked_add(1).ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "lane {} incarnation generation overflow",
                        lane.id
                    ))
                })?
            };
            let encoded = (
                chain_id.clone(),
                previous_catalog_hash,
                lane.id,
                lane.clone(),
                prior.generation,
                prior.incarnation,
                prior.activation_height,
                next_generation,
            )
                .encode();
            Hash::new_from_chunks(&[
                LIFECYCLE_LANE_INCARNATION_DOMAIN,
                committing_header_hash.as_ref(),
                prior_present.as_slice(),
                encoded.as_slice(),
            ])
        } else {
            previous_incarnations
                .get(&lane.id)
                .copied()
                .ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "unchanged lane {} is missing its prior incarnation",
                        lane.id
                    ))
                })?
        };
        if lane_incarnation_is_zero(incarnation) {
            return Err(LaneLifecycleError::LaneIncarnationState(format!(
                "derived all-zero incarnation for lane {}",
                lane.id
            )));
        }
        updated.insert(lane.id, incarnation);
    }
    validate_lane_incarnation_map(updated_catalog, &updated)?;
    Ok(updated)
}

struct PendingDaCommitmentBundle {
    block_height: u64,
    bundle: iroha_data_model::da::commitment::DaCommitmentBundle,
}

struct PendingDaPinIntentBundle {
    block_height: u64,
    intents: Vec<iroha_data_model::da::pin_intent::DaPinIntent>,
}

#[derive(Default)]
struct DaPinIntentIndexPruneKeys {
    tickets: BTreeSet<StorageTicketId>,
    aliases: BTreeSet<String>,
    manifests: BTreeSet<ManifestDigest>,
    lane_epochs: BTreeSet<(LaneId, u64, u64)>,
}

impl DaPinIntentIndexPruneKeys {
    fn is_empty(&self) -> bool {
        self.tickets.is_empty()
            && self.aliases.is_empty()
            && self.manifests.is_empty()
            && self.lane_epochs.is_empty()
    }
}

#[derive(Clone)]
struct PendingAutoscaleLaneLifecycle {
    catalog_update: LaneLifecycleCatalogUpdate,
    updated_lane_manifests: LaneManifestRegistryHandle,
    plan: iroha_data_model::nexus::LaneLifecyclePlan,
    transition: PendingAutoscaleTransition,
    transition_height: u64,
    expected_incarnation_root: Hash,
}

impl PendingAutoscaleLaneLifecycle {
    fn exact_scale_in_binding(
        &self,
    ) -> Result<Option<(LaneId, DataSpaceId, Hash)>, LaneLifecycleError> {
        let PendingAutoscaleTransition::ScaleIn { lane, .. } = &self.transition else {
            return Ok(None);
        };
        ensure_autoscale_transition_matches_plan(&self.plan, &self.transition)?;
        let previous_lane = self
            .catalog_update
            .previous_catalog
            .lanes()
            .iter()
            .find(|candidate| candidate.id == *lane)
            .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: *lane,
                reason: "final Queue veto cannot resolve the retiring lane in the previous catalog",
            })?;
        let incarnation = self
            .catalog_update
            .previous_lane_incarnations
            .get(lane)
            .copied()
            .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: *lane,
                reason: "final Queue veto cannot resolve the retiring lane incarnation",
            })?;
        Ok(Some((*lane, previous_lane.dataspace_id, incarnation)))
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum AutoscaleScaleInAction {
    RequestDrain(LaneId),
    Retire(LaneId),
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum PendingAutoscaleTransition {
    Manual,
    DrainIntent {
        lane: LaneId,
        intent: LaneDrainIntentV1,
        active_lanes: u64,
        autoscale_capacity_lanes: u64,
        in_latency_ratio_permille: u64,
        in_utilization_p95_permille: u64,
    },
    DrainCommitment {
        lane: LaneId,
        commitment: LaneDrainCommitmentV1,
    },
    ScaleOut {
        lane: LaneId,
        active_lanes: u64,
        autoscale_capacity_lanes: u64,
        out_latency_ratio_permille: u64,
        out_utilization_p95_permille: u64,
    },
    ScaleIn {
        lane: LaneId,
        active_lanes: u64,
        autoscale_capacity_lanes: u64,
        in_latency_ratio_permille: u64,
        in_utilization_p95_permille: u64,
    },
}

impl PendingAutoscaleTransition {
    fn name(&self) -> &'static str {
        match self {
            Self::Manual => "manual",
            Self::DrainIntent { .. } => "drain-intent",
            Self::DrainCommitment { .. } => "drain-commitment",
            Self::ScaleOut { .. } => "scale-out",
            Self::ScaleIn { .. } => "scale-in",
        }
    }

    fn log(&self, height: u64) {
        match self {
            Self::Manual => {
                info!(
                    height,
                    "applied consensus-replayed manual lane lifecycle transition"
                );
            }
            Self::DrainIntent {
                lane,
                intent,
                active_lanes,
                autoscale_capacity_lanes,
                in_latency_ratio_permille,
                in_utilization_p95_permille,
            } => {
                info!(
                    height,
                    lane = lane.as_u32(),
                    close_global_height = intent.close_global_height,
                    initial_merged_lane_height = intent.initial_frontier.lane_block_height,
                    active_lanes,
                    autoscale_capacity_lanes,
                    in_latency_ratio_permille,
                    in_utilization_p95_permille,
                    "committed deterministic lane autoscale drain intent"
                );
            }
            Self::DrainCommitment { lane, commitment } => {
                info!(
                    height,
                    lane = lane.as_u32(),
                    carrier_height = commitment.carrier_height,
                    final_lane_block_height = commitment.frontier.lane_block_height,
                    "committed globally certified lane autoscale drain frontier"
                );
            }
            Self::ScaleOut {
                lane,
                active_lanes,
                autoscale_capacity_lanes,
                out_latency_ratio_permille,
                out_utilization_p95_permille,
            } => {
                info!(
                    height,
                    lane = lane.as_u32(),
                    active_lanes,
                    autoscale_capacity_lanes,
                    out_latency_ratio_permille,
                    out_utilization_p95_permille,
                    "applied deterministic lane autoscale scale-out transition"
                );
            }
            Self::ScaleIn {
                lane,
                active_lanes,
                autoscale_capacity_lanes,
                in_latency_ratio_permille,
                in_utilization_p95_permille,
            } => {
                info!(
                    height,
                    lane = lane.as_u32(),
                    active_lanes,
                    autoscale_capacity_lanes,
                    in_latency_ratio_permille,
                    in_utilization_p95_permille,
                    "applied deterministic lane autoscale scale-in transition"
                );
            }
        }
    }

    const fn requires_geometry(&self) -> bool {
        !matches!(
            self,
            Self::DrainIntent { .. } | Self::DrainCommitment { .. }
        )
    }

    const fn advances_autoscale_cooldown(&self) -> bool {
        matches!(
            self,
            Self::DrainIntent { .. } | Self::ScaleOut { .. } | Self::ScaleIn { .. }
        )
    }
}

fn prepare_lane_lifecycle_update(
    nexus: &iroha_config::parameters::actual::Nexus,
    previous_lane_incarnations: &BTreeMap<LaneId, Hash>,
    previous_lane_incarnation_lineage: &BTreeMap<LaneId, LaneIncarnationLineage>,
    previous_lane_incarnation_activation_heights: &BTreeMap<LaneId, u64>,
    chain_id: &iroha_data_model::ChainId,
    committing_header_hash: HashOf<BlockHeader>,
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
    current_block_height: u64,
    allow_autoscale_managed_changes: bool,
) -> core::result::Result<LaneLifecycleCatalogUpdate, LaneLifecycleError> {
    if !nexus.enabled {
        return Err(LaneLifecycleError::NexusDisabled);
    }
    if plan.additions.is_empty() && plan.retire.is_empty() {
        return Err(LaneLifecycleError::EmptyPlan);
    }
    ensure_autoscale_runtime_lane_bounds(&nexus.autoscale)?;
    let dataspace_ids: BTreeSet<_> = nexus
        .dataspace_catalog
        .entries()
        .iter()
        .map(|entry| entry.id)
        .collect();
    for addition in &plan.additions {
        if !dataspace_ids.contains(&addition.dataspace_id) {
            return Err(LaneLifecycleError::UnknownDataspace(addition.dataspace_id));
        }
        if lane_claims_autoscale_managed(addition) {
            if !allow_autoscale_managed_changes {
                return Err(LaneLifecycleError::ReservedAutoscaleManagedLane(
                    addition.id,
                ));
            }
            ensure_autoscale_managed_lane_owned_by_nexus(addition, nexus)?;
        } else if allow_autoscale_managed_changes {
            return Err(LaneLifecycleError::AutoscaleAddUnmanagedLane(addition.id));
        } else {
            ensure_manual_lane_has_no_reserved_autoscale_metadata(addition)?;
            ensure_manual_lane_outside_autoscale_elastic_range(addition.id, nexus)?;
        }
    }
    for retire_id in &plan.retire {
        let existing_lane = nexus
            .lane_catalog
            .lanes()
            .iter()
            .find(|lane| lane.id == *retire_id);
        if allow_autoscale_managed_changes {
            if let Some(lane) = existing_lane
                && !lane_claims_autoscale_managed(lane)
            {
                return Err(LaneLifecycleError::AutoscaleRetireUnmanagedLane(*retire_id));
            }
            if let Some(lane) = existing_lane {
                ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus)?;
            }
        } else if let Some(lane) = existing_lane
            && lane_claims_autoscale_managed(lane)
            && ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus).is_ok()
            && ensure_autoscale_managed_lane_created_height_not_future(lane, current_block_height)
                .is_ok()
        {
            return Err(LaneLifecycleError::ReservedAutoscaleManagedLane(*retire_id));
        }
    }
    let retire_ids: BTreeSet<_> = plan.retire.iter().copied().collect();
    let replaced_lane_ids: BTreeSet<_> = plan
        .additions
        .iter()
        .filter_map(|addition| retire_ids.contains(&addition.id).then_some(addition.id))
        .collect();

    if retire_ids.contains(&LaneId::SINGLE) {
        return Err(LaneLifecycleError::PhysicalPrimaryReplacement);
    }

    let updated_catalog = nexus.lane_catalog.apply_lifecycle(plan)?;
    let added_lane_ids: BTreeSet<_> = plan.additions.iter().map(|lane| lane.id).collect();
    ensure_catalog_autoscale_lanes_consistent(
        nexus,
        &updated_catalog,
        current_block_height,
        &added_lane_ids,
    )?;
    validate_nexus_routing_policy(
        &nexus.routing_policy,
        &updated_catalog,
        &nexus.dataspace_catalog,
    )?;
    if replaced_lane_ids.contains(&nexus.routing_policy.default_lane) {
        return Err(LaneLifecycleError::DefaultLaneReplacement(
            nexus.routing_policy.default_lane,
        ));
    }
    let previous_lane_config = nexus.lane_config.clone();
    let updated_lane_config =
        iroha_config::parameters::actual::LaneConfig::from_catalog(&updated_catalog);
    let mut lanes_to_reset =
        lanes_requiring_state_reset(&previous_lane_config, &updated_lane_config);
    lanes_to_reset.extend(plan.additions.iter().filter_map(|addition| {
        replaced_lane_ids
            .contains(&addition.id)
            .then_some(addition.id)
    }));
    let updated_lane_incarnations = derive_lifecycle_lane_incarnations(
        chain_id,
        committing_header_hash,
        &nexus.lane_catalog,
        &updated_catalog,
        previous_lane_incarnations,
        previous_lane_incarnation_activation_heights,
        previous_lane_incarnation_lineage,
        plan,
    )?;
    let updated_lane_incarnation_activation_heights =
        derive_lifecycle_lane_incarnation_activation_heights(
            &nexus.lane_catalog,
            &updated_catalog,
            previous_lane_incarnation_activation_heights,
            plan,
            current_block_height,
        )?;
    let mut updated_lane_incarnation_lineage = previous_lane_incarnation_lineage.clone();
    for (&lane_id, &incarnation) in &updated_lane_incarnations {
        let activation_height = updated_lane_incarnation_activation_heights[&lane_id];
        let generation = if previous_lane_incarnations.get(&lane_id) == Some(&incarnation) {
            previous_lane_incarnation_lineage
                .get(&lane_id)
                .ok_or_else(|| {
                    LaneLifecycleError::LaneIncarnationState(format!(
                        "unchanged lane {lane_id} is missing its retained lineage"
                    ))
                })?
                .generation
        } else {
            previous_lane_incarnation_lineage
                .get(&lane_id)
                .map_or(Ok(0), |prior| {
                    prior.generation.checked_add(1).ok_or_else(|| {
                        LaneLifecycleError::LaneIncarnationState(format!(
                            "lane {lane_id} incarnation generation overflow"
                        ))
                    })
                })?
        };
        updated_lane_incarnation_lineage.insert(
            lane_id,
            LaneIncarnationLineage {
                generation,
                incarnation,
                activation_height,
            },
        );
    }
    validate_lane_incarnation_lineage(
        &updated_catalog,
        &updated_lane_incarnations,
        &updated_lane_incarnation_activation_heights,
        &updated_lane_incarnation_lineage,
    )?;
    Ok(LaneLifecycleCatalogUpdate {
        previous_catalog: nexus.lane_catalog.clone(),
        previous_dataspace_catalog: nexus.dataspace_catalog.clone(),
        previous_routing_policy: nexus.routing_policy.clone(),
        previous_autoscale: nexus.autoscale,
        updated_catalog,
        previous_lane_config,
        updated_lane_config,
        previous_lane_incarnations: previous_lane_incarnations.clone(),
        updated_lane_incarnations,
        previous_lane_incarnation_lineage: previous_lane_incarnation_lineage.clone(),
        updated_lane_incarnation_lineage,
        previous_lane_incarnation_activation_heights: previous_lane_incarnation_activation_heights
            .clone(),
        updated_lane_incarnation_activation_heights,
        lanes_to_reset,
        replaced_lane_ids,
    })
}

fn lane_claims_autoscale_managed(lane: &iroha_data_model::nexus::LaneConfig) -> bool {
    lane.claims_autoscale_managed()
}

fn decode_autoscale_lane_drain_state(
    lane: &iroha_data_model::nexus::LaneConfig,
) -> Result<Option<LaneDrainStateV1>, &'static str> {
    let Some(encoded_hex) = lane.metadata.get(AUTOSCALE_META_DRAIN_STATE) else {
        return Ok(None);
    };
    if encoded_hex.is_empty()
        || encoded_hex.len() % 2 != 0
        || encoded_hex.len() > MAX_AUTOSCALE_DRAIN_STATE_BYTES.saturating_mul(2)
    {
        return Err("autoscale.drain_state must be bounded canonical hex");
    }
    let encoded = hex::decode(encoded_hex)
        .map_err(|_| "autoscale.drain_state must be bounded canonical hex")?;
    if encoded.len() > MAX_AUTOSCALE_DRAIN_STATE_BYTES {
        return Err("autoscale.drain_state exceeds its canonical byte limit");
    }
    let state = norito::decode_from_bytes::<LaneDrainStateV1>(&encoded)
        .map_err(|_| "autoscale.drain_state must decode canonically")?;
    let canonical =
        norito::to_bytes(&state).map_err(|_| "autoscale.drain_state must encode canonically")?;
    if canonical != encoded || hex::encode(&canonical) != *encoded_hex {
        return Err("autoscale.drain_state is not canonical");
    }
    if state.version != 1
        || state.intent.lane_id != lane.id
        || state.intent.dataspace_id != lane.dataspace_id
        || crate::lane_consensus::validate_lane_drain_intent(&state.intent).is_err()
    {
        return Err("autoscale.drain_state intent does not match its lane");
    }
    if let Some(commitment) = state.commitment {
        if commitment.version != 1
            || commitment.carrier_height <= state.intent.close_global_height
            || commitment.frontier.lane_block_height
                < state.intent.initial_frontier.lane_block_height
            || !commitment.frontier.matches_route(
                state.intent.lane_id,
                state.intent.dataspace_id,
                state.intent.lane_incarnation,
            )
            || crate::lane_consensus::validate_lane_drain_frontier(&commitment.frontier).is_err()
            || commitment
                .certificate_hash
                .as_ref()
                .iter()
                .all(|byte| *byte == 0)
            || commitment
                .merge_entry_hash
                .as_ref()
                .iter()
                .all(|byte| *byte == 0)
        {
            return Err("autoscale.drain_state commitment is malformed");
        }
    }
    Ok(Some(state))
}

fn encode_autoscale_lane_drain_state(
    state: &LaneDrainStateV1,
) -> Result<String, LaneLifecycleError> {
    let encoded = norito::to_bytes(state).map_err(|err| {
        LaneLifecycleError::Storage(format!("encode autoscale lane drain state: {err}"))
    })?;
    if encoded.len() > MAX_AUTOSCALE_DRAIN_STATE_BYTES {
        return Err(LaneLifecycleError::Storage(format!(
            "autoscale lane drain state exceeds {MAX_AUTOSCALE_DRAIN_STATE_BYTES} bytes"
        )));
    }
    Ok(hex::encode(encoded))
}

fn validate_autoscale_lane_committee_shape(
    committee: &AutoscaleLaneCommitteeV1,
) -> Result<(), &'static str> {
    let validator_count = usize::try_from(committee.validator_count)
        .map_err(|_| "autoscale committee validator count does not fit memory")?;
    let expected_quorum =
        crate::sumeragi::network_topology::commit_quorum_from_len(validator_count);
    if committee.version != 1
        || committee.validator_set_hash_version != VALIDATOR_SET_HASH_VERSION_V1
        || validator_count == 0
        || !lane_committee_size_within_protocol_limit(validator_count)
        || committee.validator_set.len() != validator_count
        || committee.validator_pops.len() != validator_count
        || committee.validator_set_hash != HashOf::new(&committee.validator_set)
        || committee
            .validator_set
            .windows(2)
            .any(|pair| pair[0] >= pair[1])
        || committee
            .validator_set
            .iter()
            .any(|peer| peer.public_key().algorithm() != Algorithm::BlsNormal)
        || committee
            .validator_pops
            .iter()
            .any(|pop| pop.len() != crate::lane_consensus::LANE_BLS_PROOF_BYTES)
        || usize::try_from(committee.min_quorum).ok() != Some(expected_quorum)
    {
        return Err("autoscale committee shape, hash, ordering, algorithm, or quorum is invalid");
    }
    Ok(())
}

fn validate_autoscale_lane_committee_pops(
    committee: &AutoscaleLaneCommitteeV1,
) -> Result<(), &'static str> {
    if committee
        .validator_set
        .iter()
        .zip(&committee.validator_pops)
        .any(|(peer, pop)| iroha_crypto::bls_normal_pop_verify(peer.public_key(), pop).is_err())
    {
        return Err("autoscale committee contains an invalid BLS proof-of-possession");
    }
    Ok(())
}

fn decode_autoscale_lane_committee(
    lane: &iroha_data_model::nexus::LaneConfig,
) -> Result<Option<AutoscaleLaneCommitteeV1>, &'static str> {
    let Some(encoded_hex) = lane.metadata.get(AUTOSCALE_META_COMMITTEE) else {
        return Ok(None);
    };
    if encoded_hex.is_empty()
        || encoded_hex.len() % 2 != 0
        || encoded_hex.len() > MAX_AUTOSCALE_COMMITTEE_BYTES.saturating_mul(2)
    {
        return Err("autoscale committee must be bounded canonical hex");
    }
    let encoded = hex::decode(encoded_hex)
        .map_err(|_| "autoscale committee must be bounded canonical hex")?;
    if encoded.len() > MAX_AUTOSCALE_COMMITTEE_BYTES {
        return Err("autoscale committee exceeds its canonical byte limit");
    }
    let committee = norito::decode_from_bytes::<AutoscaleLaneCommitteeV1>(&encoded)
        .map_err(|_| "autoscale committee must decode canonically")?;
    let canonical =
        norito::to_bytes(&committee).map_err(|_| "autoscale committee must encode canonically")?;
    if canonical != encoded || hex::encode(&canonical) != *encoded_hex {
        return Err("autoscale committee is not canonical");
    }
    validate_autoscale_lane_committee_shape(&committee)?;
    Ok(Some(committee))
}

/// Return the exact historical BLS committee and proofs-of-possession pinned to
/// an autoscale lane incarnation.
///
/// Missing or malformed metadata fails closed as `None`; callers must not fall
/// back to a mutable live-key cache for an autoscale-managed lane.
pub(crate) fn autoscale_lane_pinned_committee_with_pops(
    lane: &iroha_data_model::nexus::LaneConfig,
) -> Option<Vec<(PeerId, Vec<u8>)>> {
    let committee = decode_autoscale_lane_committee(lane).ok().flatten()?;
    Some(
        committee
            .validator_set
            .into_iter()
            .zip(committee.validator_pops)
            .collect(),
    )
}

fn encode_autoscale_lane_committee(
    committee: &AutoscaleLaneCommitteeV1,
) -> Result<String, LaneLifecycleError> {
    validate_autoscale_lane_committee_shape(committee).map_err(|reason| {
        LaneLifecycleError::Storage(format!("encode autoscale lane committee: {reason}"))
    })?;
    validate_autoscale_lane_committee_pops(committee).map_err(|reason| {
        LaneLifecycleError::Storage(format!("encode autoscale lane committee: {reason}"))
    })?;
    let encoded = norito::to_bytes(committee).map_err(|err| {
        LaneLifecycleError::Storage(format!("encode autoscale lane committee: {err}"))
    })?;
    if encoded.len() > MAX_AUTOSCALE_COMMITTEE_BYTES {
        return Err(LaneLifecycleError::Storage(format!(
            "autoscale lane committee exceeds {MAX_AUTOSCALE_COMMITTEE_BYTES} bytes"
        )));
    }
    Ok(hex::encode(encoded))
}

fn autoscale_lane_committee_from_validator_set(
    validator_set: Vec<PeerId>,
    validator_pops: Vec<Vec<u8>>,
) -> Result<AutoscaleLaneCommitteeV1, LaneLifecycleError> {
    let validator_count = u32::try_from(validator_set.len()).map_err(|_| {
        LaneLifecycleError::Storage("autoscale committee length does not fit u32".to_owned())
    })?;
    let min_quorum = u32::try_from(crate::sumeragi::network_topology::commit_quorum_from_len(
        validator_set.len(),
    ))
    .map_err(|_| {
        LaneLifecycleError::Storage("autoscale committee quorum does not fit u32".to_owned())
    })?;
    let committee = AutoscaleLaneCommitteeV1 {
        version: 1,
        validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
        validator_set_hash: HashOf::new(&validator_set),
        validator_set,
        validator_pops,
        validator_count,
        min_quorum,
    };
    validate_autoscale_lane_committee_shape(&committee).map_err(|reason| {
        LaneLifecycleError::Storage(format!("construct autoscale lane committee: {reason}"))
    })?;
    validate_autoscale_lane_committee_pops(&committee).map_err(|reason| {
        LaneLifecycleError::Storage(format!("construct autoscale lane committee: {reason}"))
    })?;
    Ok(committee)
}

#[cfg(test)]
fn synthetic_autoscale_committee_keypairs_for_test() -> Vec<KeyPair> {
    let mut members = (0_u8..4)
        .map(|index| {
            KeyPair::try_from_seed(
                vec![0x91_u8.saturating_add(index); 32],
                Algorithm::BlsNormal,
            )
            .expect("deterministic synthetic autoscale committee key")
        })
        .collect::<Vec<_>>();
    members.sort_by(|left, right| {
        PeerId::new(left.public_key().clone()).cmp(&PeerId::new(right.public_key().clone()))
    });
    members
}

#[cfg(test)]
/// Attach a deterministic valid committee pin to a sibling unit-test fixture.
pub(crate) fn attach_synthetic_autoscale_committee_for_test(
    lane: &mut iroha_data_model::nexus::LaneConfig,
) {
    let members = synthetic_autoscale_committee_keypairs_for_test();
    let validator_set = members
        .iter()
        .map(|keypair| PeerId::new(keypair.public_key().clone()))
        .collect::<Vec<_>>();
    let validator_pops = members
        .iter()
        .map(|keypair| {
            iroha_crypto::bls_normal_pop_prove(keypair.private_key())
                .expect("synthetic autoscale committee PoP")
        })
        .collect::<Vec<_>>();
    let committee = autoscale_lane_committee_from_validator_set(validator_set, validator_pops)
        .expect("valid synthetic autoscale committee");
    lane.metadata.insert(
        AUTOSCALE_META_COMMITTEE.to_owned(),
        encode_autoscale_lane_committee(&committee)
            .expect("canonical synthetic autoscale committee"),
    );
}

/// Return whether one autoscale-managed lane may accept a proposal at `height`.
///
/// Missing drain metadata leaves a correctly pinned lane open, canonical drain
/// metadata keeps it open through the exact close height, and malformed or
/// missing incarnation authority fails closed.
pub(crate) fn autoscale_lane_accepts_proposal_height(
    lane: &iroha_data_model::nexus::LaneConfig,
    height: u64,
) -> bool {
    if lane_claims_autoscale_managed(lane)
        && !matches!(decode_autoscale_lane_committee(lane), Ok(Some(_)))
    {
        return false;
    }
    match decode_autoscale_lane_drain_state(lane) {
        Ok(Some(state)) => height <= state.intent.close_global_height,
        Ok(None) => true,
        Err(_) => false,
    }
}

fn autoscale_catalog_with_lane_drain_state(
    nexus: &iroha_config::parameters::actual::Nexus,
    lane_id: LaneId,
    state: &LaneDrainStateV1,
) -> Result<LaneCatalog, LaneLifecycleError> {
    let encoded = encode_autoscale_lane_drain_state(state)?;
    let mut lanes = nexus.lane_catalog.lanes().to_vec();
    let lane = lanes.iter_mut().find(|lane| lane.id == lane_id).ok_or(
        LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane_id,
            reason: "drain transition lane is absent from the catalog",
        },
    )?;
    ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus)?;
    if state.intent.lane_id != lane.id || state.intent.dataspace_id != lane.dataspace_id {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane_id,
            reason: "drain transition intent does not match its lane",
        });
    }
    lane.metadata
        .insert(AUTOSCALE_META_DRAIN_STATE.to_owned(), encoded);
    let catalog = LaneCatalog::new(nexus.lane_catalog.lane_count(), lanes).map_err(|err| {
        LaneLifecycleError::Storage(format!("build autoscale drain-state catalog: {err}"))
    })?;
    let updated_lane = catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
        .expect("updated autoscale drain lane must remain in the catalog");
    if decode_autoscale_lane_drain_state(updated_lane)
        .ok()
        .flatten()
        != Some(state.clone())
    {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane_id,
            reason: "drain transition state is not exact canonical metadata",
        });
    }
    Ok(catalog)
}

fn lane_without_autoscale_drain_metadata(
    lane: &iroha_data_model::nexus::LaneConfig,
) -> iroha_data_model::nexus::LaneConfig {
    let mut lane = lane.clone();
    lane.metadata.remove(AUTOSCALE_META_DRAIN_STATE);
    lane
}

fn merge_lane_config_hash(lane: &iroha_data_model::nexus::LaneConfig) -> Hash {
    crate::merge::merge_lane_config_hash(&lane_without_autoscale_drain_metadata(lane))
}

fn merge_lane_catalog_hash(catalog: &LaneCatalog) -> Hash {
    let lanes = catalog
        .lanes()
        .iter()
        .map(lane_without_autoscale_drain_metadata)
        .collect();
    let sanitized = LaneCatalog::new(catalog.lane_count(), lanes)
        .expect("removing reserved drain metadata cannot invalidate a lane catalog");
    iroha_data_model::nexus::LaneLifecycleParameterV1::catalog_hash(&sanitized)
}

fn autoscale_lane_drain_state_matches_context(
    lane: &iroha_data_model::nexus::LaneConfig,
    state: &LaneDrainStateV1,
    chain_id: &iroha_data_model::ChainId,
    lane_incarnation: Hash,
) -> bool {
    let Ok(Some(committee)) = decode_autoscale_lane_committee(lane) else {
        return false;
    };
    state.intent.chain_id_digest == crate::merge::merge_chain_id_digest(chain_id)
        && state.intent.lane_id == lane.id
        && state.intent.dataspace_id == lane.dataspace_id
        && state.intent.lane_incarnation == lane_incarnation
        && state.intent.validator_set_hash_version == committee.validator_set_hash_version
        && state.intent.validator_set_hash == committee.validator_set_hash
        && state.intent.validator_set == committee.validator_set
        && state.intent.validator_count == committee.validator_count
        && state.intent.min_quorum == committee.min_quorum
}

fn lane_uses_reserved_autoscale_metadata(lane: &iroha_data_model::nexus::LaneConfig) -> bool {
    lane.metadata.contains_key(AUTOSCALE_META_MANAGED)
        || lane.metadata.contains_key(AUTOSCALE_META_CREATED_HEIGHT)
        || lane.metadata.contains_key(AUTOSCALE_META_DRAIN_STATE)
        || lane.metadata.contains_key(AUTOSCALE_META_COMMITTEE)
}

fn ensure_manual_lane_has_no_reserved_autoscale_metadata(
    lane: &iroha_data_model::nexus::LaneConfig,
) -> Result<(), LaneLifecycleError> {
    if lane_uses_reserved_autoscale_metadata(lane) {
        return Err(LaneLifecycleError::ReservedAutoscaleManagedLane(lane.id));
    }
    Ok(())
}

fn ensure_autoscale_managed_lane_shape(
    lane: &iroha_data_model::nexus::LaneConfig,
) -> Result<(), LaneLifecycleError> {
    if lane.visibility != iroha_data_model::nexus::LaneVisibility::Public {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale-managed lanes must be public",
        });
    }
    if !lane
        .metadata
        .get(AUTOSCALE_META_MANAGED)
        .is_some_and(|value| value == "true")
    {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale.managed must be exactly `true`",
        });
    }
    let expected_alias = format!("elastic-lane-{}", lane.id.as_u32());
    if lane.alias != expected_alias {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "alias must match elastic-lane-{id}",
        });
    }
    if lane.autoscale_created_height().is_none() {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale.created_height must be a positive integer",
        });
    }
    if decode_autoscale_lane_drain_state(lane).is_err() {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale.drain_state must be bounded, canonical, and match the lane",
        });
    }
    if !matches!(decode_autoscale_lane_committee(lane), Ok(Some(_))) {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale.committee_v1 must be present, bounded, canonical, and valid",
        });
    }
    Ok(())
}

fn ensure_autoscale_managed_lane_owned_by_nexus(
    lane: &iroha_data_model::nexus::LaneConfig,
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Result<(), LaneLifecycleError> {
    ensure_autoscale_managed_lane_shape(lane)?;
    if !nexus.autoscale.enabled {
        return Err(LaneLifecycleError::AutoscaleManagedLaneDisabled(lane.id));
    }
    ensure_autoscale_managed_lane_in_range(
        lane.id,
        nexus.autoscale.min_lanes.get(),
        nexus.autoscale.max_lanes.get(),
    )?;
    ensure_autoscale_managed_lane_default_dataspace(lane, nexus.routing_policy.default_dataspace)?;
    let committee = decode_autoscale_lane_committee(lane).ok().flatten().ok_or(
        LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale committee metadata is missing or malformed",
        },
    )?;
    let required = nexus_lane_committee_size(nexus, lane.dataspace_id).ok_or(
        LaneLifecycleError::AutoscaleCommitteeSizeInvalid {
            lane: lane.id,
            dataspace: lane.dataspace_id,
        },
    )?;
    if committee.validator_set.len() != required {
        return Err(LaneLifecycleError::AutoscaleCommitteeUnavailable {
            lane: lane.id,
            dataspace: lane.dataspace_id,
            required,
            actual: committee.validator_set.len(),
        });
    }
    ensure_autoscale_managed_lane_inherits_default_profile(lane, nexus)
}

const AUTOSCALE_RESTRICTED_BASE_REASON: &str =
    "routing default lane must be public for autoscale-managed lanes";
const AUTOSCALE_PROFILE_DRIFT_REASON: &str = "profile must match the routing default lane";

fn ensure_autoscale_managed_lane_inherits_default_profile(
    lane: &iroha_data_model::nexus::LaneConfig,
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Result<(), LaneLifecycleError> {
    let base_lane = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|candidate| candidate.id == nexus.routing_policy.default_lane)
        .ok_or_else(|| {
            LaneLifecycleError::RoutingPolicy(format!(
                "default lane {} is not present in the lane catalog",
                nexus.routing_policy.default_lane
            ))
        })?;
    if base_lane.visibility != iroha_data_model::nexus::LaneVisibility::Public {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: AUTOSCALE_RESTRICTED_BASE_REASON,
        });
    }
    if !lane.inherits_autoscale_profile_from(base_lane) {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: AUTOSCALE_PROFILE_DRIFT_REASON,
        });
    }
    Ok(())
}

fn ensure_autoscale_managed_lane_created_height_not_future(
    lane: &iroha_data_model::nexus::LaneConfig,
    block_height: u64,
) -> Result<(), LaneLifecycleError> {
    let created_height =
        lane.autoscale_created_height()
            .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: lane.id,
                reason: "autoscale.created_height must be a positive integer",
            })?;
    if created_height > block_height {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale.created_height must not exceed the current block height",
        });
    }
    if let Some(drain_state) = decode_autoscale_lane_drain_state(lane).map_err(|reason| {
        LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason,
        }
    })? && drain_state.intent.close_global_height < created_height
    {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale drain close height must not precede lane creation",
        });
    }
    Ok(())
}

fn ensure_autoscale_lane_drain_close_not_future(
    lane: &iroha_data_model::nexus::LaneConfig,
    block_height: u64,
) -> Result<(), LaneLifecycleError> {
    if decode_autoscale_lane_drain_state(lane)
        .map_err(|reason| LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason,
        })?
        .is_some_and(|state| state.intent.close_global_height > block_height)
    {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale drain close height must not exceed the current block height",
        });
    }
    Ok(())
}

fn ensure_autoscale_managed_lane_created_height_is_current(
    lane: &iroha_data_model::nexus::LaneConfig,
    block_height: u64,
) -> Result<(), LaneLifecycleError> {
    let created_height =
        lane.autoscale_created_height()
            .ok_or(LaneLifecycleError::InvalidAutoscaleManagedLane {
                lane: lane.id,
                reason: "autoscale.created_height must be a positive integer",
            })?;
    if created_height != block_height {
        return Err(LaneLifecycleError::InvalidAutoscaleManagedLane {
            lane: lane.id,
            reason: "autoscale.created_height must equal the current block height",
        });
    }
    Ok(())
}

fn ensure_autoscale_transition_matches_plan(
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
    transition: &PendingAutoscaleTransition,
) -> Result<(), LaneLifecycleError> {
    match transition {
        PendingAutoscaleTransition::Manual => Ok(()),
        PendingAutoscaleTransition::DrainIntent { .. } => {
            if plan.additions.is_empty() && plan.retire.is_empty() {
                Ok(())
            } else {
                Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
                    transition: "drain-intent",
                    reason: "requires an empty geometry plan",
                })
            }
        }
        PendingAutoscaleTransition::DrainCommitment { .. } => {
            if plan.additions.is_empty() && plan.retire.is_empty() {
                Ok(())
            } else {
                Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
                    transition: "drain-commitment",
                    reason: "requires an empty geometry plan",
                })
            }
        }
        PendingAutoscaleTransition::ScaleOut { lane, .. } => {
            if plan.retire.is_empty() && plan.additions.len() == 1 && plan.additions[0].id == *lane
            {
                Ok(())
            } else {
                Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
                    transition: "scale-out",
                    reason: "requires exactly one addition for the transition lane and no retirements",
                })
            }
        }
        PendingAutoscaleTransition::ScaleIn { lane, .. } => {
            if plan.additions.is_empty() && plan.retire.len() == 1 && plan.retire[0] == *lane {
                Ok(())
            } else {
                Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
                    transition: "scale-in",
                    reason: "requires exactly one retirement for the transition lane and no additions",
                })
            }
        }
    }
}

fn ensure_autoscale_transition_capacity_matches_nexus(
    nexus: &iroha_config::parameters::actual::Nexus,
    transition: &PendingAutoscaleTransition,
) -> Result<(), LaneLifecycleError> {
    let (transition_name, active_lanes, autoscale_capacity_lanes) = match transition {
        PendingAutoscaleTransition::Manual => return Ok(()),
        PendingAutoscaleTransition::DrainIntent {
            active_lanes,
            autoscale_capacity_lanes,
            ..
        } => ("drain-intent", active_lanes, autoscale_capacity_lanes),
        PendingAutoscaleTransition::DrainCommitment { .. } => return Ok(()),
        PendingAutoscaleTransition::ScaleOut {
            active_lanes,
            autoscale_capacity_lanes,
            ..
        } => ("scale-out", active_lanes, autoscale_capacity_lanes),
        PendingAutoscaleTransition::ScaleIn {
            active_lanes,
            autoscale_capacity_lanes,
            ..
        } => ("scale-in", active_lanes, autoscale_capacity_lanes),
    };
    let current_capacity = autoscale_default_route_capacity_lanes(
        &nexus.routing_policy,
        nexus.lane_catalog.lanes(),
        nexus.autoscale.min_lanes.get(),
        nexus.autoscale.max_lanes.get(),
    );
    if current_capacity != 0
        && *active_lanes == current_capacity
        && *autoscale_capacity_lanes == current_capacity
    {
        return Ok(());
    }
    Err(LaneLifecycleError::AutoscaleTransitionPlanMismatch {
        transition: transition_name,
        reason: "active_lanes and autoscale_capacity_lanes must match current autoscale capacity",
    })
}

fn ensure_autoscale_managed_created_heights_not_future(
    nexus: &iroha_config::parameters::actual::Nexus,
    block_height: u64,
) -> Result<(), LaneLifecycleError> {
    if !nexus.enabled || !nexus.autoscale.enabled {
        return Ok(());
    }
    for lane in nexus.lane_catalog.lanes() {
        if !lane_claims_autoscale_managed(lane) {
            continue;
        }
        ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus)?;
        ensure_autoscale_managed_lane_created_height_not_future(lane, block_height)?;
        ensure_autoscale_lane_drain_close_not_future(lane, block_height)?;
    }
    Ok(())
}

fn nexus_fee_asset_selector_is_xor(value: &str) -> bool {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return false;
    }
    let syntactically_valid = AssetDefinitionId::parse_address_literal(trimmed).is_ok()
        || AssetDefinitionAlias::from_str(trimmed).is_ok();
    if !syntactically_valid {
        return false;
    }
    let default_xor = iroha_config::parameters::defaults::nexus::fees::fee_asset_id();
    trimmed == default_xor
        || trimmed.eq_ignore_ascii_case("xor#universal")
        || trimmed.eq_ignore_ascii_case("xor#universal.universal")
}

fn ensure_autoscale_managed_lane_in_range(
    lane: LaneId,
    min_lanes: u32,
    max_lanes: u32,
) -> Result<(), LaneLifecycleError> {
    let lane_id = lane.as_u32();
    if lane_id >= min_lanes && lane_id < max_lanes {
        return Ok(());
    }
    Err(LaneLifecycleError::AutoscaleManagedLaneOutOfBounds {
        lane,
        min_lanes,
        max_lanes,
    })
}

fn ensure_manual_lane_outside_autoscale_elastic_range(
    lane: LaneId,
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Result<(), LaneLifecycleError> {
    if !nexus.enabled || !nexus.autoscale.enabled {
        return Ok(());
    }
    let lane_id = lane.as_u32();
    let min_lanes = nexus.autoscale.min_lanes.get();
    let max_lanes = nexus.autoscale.max_lanes.get();
    if lane_id < min_lanes || lane_id >= max_lanes {
        return Ok(());
    }
    Err(LaneLifecycleError::ReservedAutoscaleElasticLaneId {
        lane,
        min_lanes,
        max_lanes,
    })
}

fn ensure_autoscale_default_lane_is_base(
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Result<(), LaneLifecycleError> {
    if !nexus.enabled || !nexus.autoscale.enabled {
        return Ok(());
    }
    let lane = nexus.routing_policy.default_lane;
    let lane_id = lane.as_u32();
    let min_lanes = nexus.autoscale.min_lanes.get();
    if lane_id < min_lanes {
        return Ok(());
    }
    Err(LaneLifecycleError::AutoscaleDefaultLaneNotBase { lane, min_lanes })
}

fn ensure_autoscale_base_profile_supported(
    nexus: &iroha_config::parameters::actual::Nexus,
    manifest_registry: Option<&LaneManifestRegistry>,
    prospective_alias: Option<&str>,
) -> Result<(), LaneLifecycleError> {
    let lane_id = nexus.routing_policy.default_lane;
    let Some(base_lane) = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
    else {
        return Err(LaneLifecycleError::RoutingPolicy(format!(
            "autoscale routing base lane {lane_id} is missing"
        )));
    };
    if base_lane.governance.is_some() {
        return Err(LaneLifecycleError::AutoscaleBaseProfileUnsupported {
            lane: lane_id,
            reason: "governance manifests are lane-alias-specific",
        });
    }
    if base_lane.storage != iroha_data_model::nexus::LaneStorageProfile::FullReplica {
        return Err(LaneLifecycleError::AutoscaleBaseProfileUnsupported {
            lane: lane_id,
            reason: "private storage profiles require lane-specific manifest commitments",
        });
    }
    if manifest_registry
        .and_then(|registry| registry.status(lane_id))
        .is_some_and(|status| {
            status.manifest_path.is_some()
                || status.rules().is_some()
                || !status.privacy_commitments().is_empty()
        })
    {
        return Err(LaneLifecycleError::AutoscaleBaseProfileUnsupported {
            lane: lane_id,
            reason: "loaded base manifest semantics are alias-specific",
        });
    }
    if prospective_alias.is_some_and(|alias| {
        manifest_registry.is_some_and(|registry| registry.has_manifest_source_alias(alias))
    }) {
        return Err(LaneLifecycleError::AutoscaleBaseProfileUnsupported {
            lane: lane_id,
            reason: "the prospective elastic alias has pre-provisioned manifest semantics that cannot be installed atomically",
        });
    }
    Ok(())
}

fn ensure_lane_lifecycle_compliance_ready(
    nexus: &iroha_config::parameters::actual::Nexus,
    engine: Option<&LaneComplianceEngine>,
    plan: &iroha_data_model::nexus::LaneLifecyclePlan,
) -> Result<(), LaneLifecycleError> {
    if !nexus.compliance.enabled {
        return Ok(());
    }
    for addition in &plan.additions {
        if !engine.is_some_and(|engine| engine.has_policy(addition.id, addition.dataspace_id)) {
            return Err(LaneLifecycleError::CompliancePolicyUnavailable { lane: addition.id });
        }
    }
    Ok(())
}

fn rebind_lane_manifests_for_lifecycle(
    registry: &LaneManifestRegistry,
    catalog: &LaneCatalog,
    governance: &iroha_config::parameters::actual::GovernanceCatalog,
) -> Result<LaneManifestRegistryHandle, LaneLifecycleError> {
    let rebound = Arc::new(registry.rebind(catalog, governance));
    rebound.validate_active_coverage().map_err(|err| {
        LaneLifecycleError::ManifestPolicyUnavailable {
            lane: err.lane,
            reason: err.message(),
        }
    })?;
    Ok(rebound)
}

fn ensure_autoscale_runtime_lane_bounds(
    autoscale: &iroha_config::parameters::actual::Autoscale,
) -> Result<(), LaneLifecycleError> {
    let min_lanes = autoscale.min_lanes.get();
    let max_lanes = autoscale.max_lanes.get();
    if min_lanes >= max_lanes {
        return Err(LaneLifecycleError::AutoscaleInvalidLaneBounds {
            min_lanes,
            max_lanes,
        });
    }
    let cap = iroha_config::parameters::defaults::nexus::autoscale::MAX_LANES;
    if max_lanes > cap {
        return Err(LaneLifecycleError::AutoscaleMaxLanesExceedsCap { max_lanes, cap });
    }
    Ok(())
}

fn ensure_autoscale_runtime_elastic_range(
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Result<(), LaneLifecycleError> {
    if !nexus.enabled || !nexus.autoscale.enabled {
        return Ok(());
    }
    ensure_autoscale_default_lane_is_base(nexus)?;
    let min_lanes = nexus.autoscale.min_lanes.get();
    let max_lanes = nexus.autoscale.max_lanes.get();
    for lane in nexus.lane_catalog.lanes() {
        let lane_id = lane.id.as_u32();
        if lane_id < min_lanes || lane_id >= max_lanes {
            if lane_claims_autoscale_managed(lane) {
                ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus)?;
            } else {
                ensure_manual_lane_has_no_reserved_autoscale_metadata(lane)?;
            }
            continue;
        }
        if !lane_claims_autoscale_managed(lane) {
            ensure_manual_lane_has_no_reserved_autoscale_metadata(lane)?;
            return Err(LaneLifecycleError::ReservedAutoscaleElasticLaneId {
                lane: lane.id,
                min_lanes,
                max_lanes,
            });
        }
        ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus)?;
    }
    Ok(())
}

fn ensure_catalog_autoscale_lanes_consistent(
    nexus: &iroha_config::parameters::actual::Nexus,
    lane_catalog: &LaneCatalog,
    current_block_height: u64,
    skip_future_height_lanes: &BTreeSet<LaneId>,
) -> Result<(), LaneLifecycleError> {
    ensure_autoscale_default_lane_is_base(nexus)?;
    for lane in lane_catalog.lanes() {
        if lane_claims_autoscale_managed(lane) {
            ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus)?;
            if !skip_future_height_lanes.contains(&lane.id) {
                ensure_autoscale_managed_lane_created_height_not_future(
                    lane,
                    current_block_height,
                )?;
                ensure_autoscale_lane_drain_close_not_future(lane, current_block_height)?;
            }
        } else {
            ensure_manual_lane_has_no_reserved_autoscale_metadata(lane)?;
            ensure_manual_lane_outside_autoscale_elastic_range(lane.id, nexus)?;
        }
    }
    Ok(())
}

fn ensure_autoscale_managed_lane_default_dataspace(
    lane: &iroha_data_model::nexus::LaneConfig,
    default_dataspace: DataSpaceId,
) -> Result<(), LaneLifecycleError> {
    if lane.dataspace_id == default_dataspace {
        return Ok(());
    }
    Err(LaneLifecycleError::AutoscaleManagedLaneWrongDataspace {
        lane: lane.id,
        dataspace: lane.dataspace_id,
        default_dataspace,
    })
}

fn nexus_lane_committee_size(
    nexus: &iroha_config::parameters::actual::Nexus,
    dataspace_id: DataSpaceId,
) -> Option<usize> {
    // Keep the exact 3f+1 shape: the canonical 2f+1 commit threshold then
    // guarantees at least f+1 members overlap between any two quorums.
    let fault_tolerance = nexus.dataspace_catalog.by_id(dataspace_id)?.fault_tolerance;
    let committee_size = fault_tolerance.checked_mul(3)?.checked_add(1)?;
    if committee_size > nexus.staking.max_validators.get() {
        return None;
    }
    let committee_size = usize::try_from(committee_size).ok()?;
    lane_committee_size_within_protocol_limit(committee_size).then_some(committee_size)
}

const fn lane_committee_size_within_protocol_limit(committee_size: usize) -> bool {
    committee_size > 0 && committee_size <= crate::lane_consensus::MAX_LANE_BLOCK_VALIDATORS
}

fn nexus_lane_active_for_authority(
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    nexus: &iroha_config::parameters::actual::Nexus,
    block_height: u64,
) -> bool {
    if nexus.dataspace_catalog.by_id(dataspace_id).is_none() {
        return false;
    }
    let Some(lane) = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
    else {
        return false;
    };
    if lane.dataspace_id != dataspace_id {
        return false;
    }
    if !lane_uses_reserved_autoscale_metadata(lane) {
        return !nexus_lane_id_in_active_autoscale_elastic_range(lane.id, nexus);
    }
    dataspace_id == nexus.routing_policy.default_dataspace
        && nexus_autoscale_lane_active_for_authority(lane, nexus, block_height)
}

fn nexus_lane_id_in_active_autoscale_elastic_range(
    lane_id: LaneId,
    nexus: &iroha_config::parameters::actual::Nexus,
) -> bool {
    if !nexus.enabled
        || !nexus.autoscale.enabled
        || ensure_autoscale_runtime_lane_bounds(&nexus.autoscale).is_err()
    {
        return false;
    }
    let lane_id = lane_id.as_u32();
    lane_id >= nexus.autoscale.min_lanes.get() && lane_id < nexus.autoscale.max_lanes.get()
}

fn nexus_autoscale_lane_active_for_authority(
    lane: &iroha_data_model::nexus::LaneConfig,
    nexus: &iroha_config::parameters::actual::Nexus,
    block_height: u64,
) -> bool {
    if !lane_claims_autoscale_managed(lane)
        || ensure_autoscale_managed_lane_owned_by_nexus(lane, nexus).is_err()
        || ensure_autoscale_managed_lane_created_height_not_future(lane, block_height).is_err()
    {
        return false;
    }
    autoscale_lane_accepts_proposal_height(lane, block_height)
}

fn validate_nexus_routing_policy(
    policy: &LaneRoutingPolicy,
    lane_catalog: &LaneCatalog,
    dataspace_catalog: &DataSpaceCatalog,
) -> Result<(), LaneLifecycleError> {
    let default_lane = lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == policy.default_lane)
        .ok_or_else(|| {
            LaneLifecycleError::RoutingPolicy(format!(
                "default lane {} is not present in the lane catalog",
                policy.default_lane
            ))
        })?;
    if dataspace_catalog.by_id(policy.default_dataspace).is_none() {
        return Err(LaneLifecycleError::RoutingPolicy(format!(
            "default dataspace {} is not present in the dataspace catalog",
            policy.default_dataspace
        )));
    }
    if default_lane.dataspace_id != policy.default_dataspace {
        return Err(LaneLifecycleError::RoutingPolicy(format!(
            "default lane {} is bound to dataspace {}, but default dataspace is {}",
            policy.default_lane, default_lane.dataspace_id, policy.default_dataspace
        )));
    }

    for (rule_index, rule) in policy.rules.iter().enumerate() {
        let rule_lane = lane_catalog
            .lanes()
            .iter()
            .find(|lane| lane.id == rule.lane)
            .ok_or_else(|| {
                LaneLifecycleError::RoutingPolicy(format!(
                    "routing rule {rule_index} lane {} is not present in the lane catalog",
                    rule.lane
                ))
            })?;
        if lane_claims_autoscale_managed(rule_lane) {
            return Err(LaneLifecycleError::RoutingPolicy(format!(
                "routing rule {rule_index} lane {} claims autoscale ownership and cannot be an explicit rule target",
                rule.lane
            )));
        }
        let dataspace_id = if let Some(dataspace_id) = rule.dataspace {
            if dataspace_catalog.by_id(dataspace_id).is_none() {
                return Err(LaneLifecycleError::RoutingPolicy(format!(
                    "routing rule {rule_index} dataspace {dataspace_id} is not present in the dataspace catalog"
                )));
            }
            dataspace_id
        } else {
            policy.default_dataspace
        };
        let dataspace_label = if rule.dataspace.is_some() {
            "rule dataspace"
        } else {
            "default dataspace"
        };
        if rule_lane.dataspace_id != dataspace_id {
            return Err(LaneLifecycleError::RoutingPolicy(format!(
                "routing rule {rule_index} lane {} is bound to dataspace {}, but {dataspace_label} is {dataspace_id}",
                rule.lane, rule_lane.dataspace_id
            )));
        }
    }

    Ok(())
}

fn lanes_requiring_state_prune(
    previous: &iroha_config::parameters::actual::LaneConfig,
    current: &iroha_config::parameters::actual::LaneConfig,
) -> BTreeSet<LaneId> {
    previous
        .entries()
        .iter()
        .filter_map(|entry| match current.entry(entry.lane_id) {
            None => Some(entry.lane_id),
            Some(updated) if !lane_reset_identity_matches(entry, updated) => Some(entry.lane_id),
            _ => None,
        })
        .collect()
}

fn lane_consensus_identity_matches(
    previous: &iroha_data_model::nexus::LaneConfig,
    current: &iroha_data_model::nexus::LaneConfig,
) -> bool {
    crate::merge::merge_lane_config_hash(previous) == crate::merge::merge_lane_config_hash(current)
}

fn lanes_requiring_consensus_reset(
    previous: &LaneCatalog,
    current: &LaneCatalog,
) -> BTreeSet<LaneId> {
    let previous_by_lane = previous
        .lanes()
        .iter()
        .map(|lane| (lane.id, lane))
        .collect::<BTreeMap<_, _>>();
    let current_by_lane = current
        .lanes()
        .iter()
        .map(|lane| (lane.id, lane))
        .collect::<BTreeMap<_, _>>();
    previous_by_lane
        .keys()
        .chain(current_by_lane.keys())
        .copied()
        .filter(
            |lane_id| match (previous_by_lane.get(lane_id), current_by_lane.get(lane_id)) {
                (Some(previous), Some(current)) => {
                    !lane_consensus_identity_matches(previous, current)
                }
                _ => true,
            },
        )
        .collect()
}

fn lane_reset_identity_matches(previous: &LaneConfigEntry, current: &LaneConfigEntry) -> bool {
    previous.lane_id == current.lane_id
        && previous.shard_id == current.shard_id
        && previous.dataspace_id == current.dataspace_id
        && previous.visibility == current.visibility
        && previous.storage_profile == current.storage_profile
        && previous.proof_scheme == current.proof_scheme
        && previous.manifest_policy == current.manifest_policy
        && previous.confidential_compute == current.confidential_compute
        && previous.confidential_policy == current.confidential_policy
        && previous.confidential_access == current.confidential_access
}

fn lane_config_entries_match(
    previous: &iroha_config::parameters::actual::LaneConfig,
    current: &iroha_config::parameters::actual::LaneConfig,
) -> bool {
    previous.entries().len() == current.entries().len()
        && previous
            .entries()
            .iter()
            .zip(current.entries())
            .all(|(previous, current)| lane_config_entry_matches(previous, current))
}

fn lane_config_entry_matches(previous: &LaneConfigEntry, current: &LaneConfigEntry) -> bool {
    lane_reset_identity_matches(previous, current)
        && previous.alias == current.alias
        && previous.slug == current.slug
        && previous.kura_segment == current.kura_segment
        && previous.merge_segment == current.merge_segment
        && previous.key_prefix == current.key_prefix
}

fn lanes_requiring_state_reset(
    previous: &iroha_config::parameters::actual::LaneConfig,
    current: &iroha_config::parameters::actual::LaneConfig,
) -> BTreeSet<LaneId> {
    let mut lanes = lanes_requiring_state_prune(previous, current);
    for entry in current.entries() {
        if previous.entry(entry.lane_id).is_none() {
            lanes.insert(entry.lane_id);
        }
    }
    lanes
}

fn lane_topology_diff<'a>(
    previous: &'a iroha_config::parameters::actual::LaneConfig,
    current: &'a iroha_config::parameters::actual::LaneConfig,
    replaced_lane_ids: &BTreeSet<LaneId>,
) -> LaneTopologyDiff<'a> {
    let mut previous_map = BTreeMap::new();
    for entry in previous.entries() {
        previous_map.insert(entry.lane_id, entry);
    }

    let mut current_map = BTreeMap::new();
    for entry in current.entries() {
        current_map.insert(entry.lane_id, entry);
    }

    let replacements = replaced_lane_ids
        .iter()
        .filter_map(|id| {
            previous_map
                .get(id)
                .zip(current_map.get(id))
                .map(|(previous, current)| (*previous, *current))
        })
        .collect();

    let added = current_map
        .iter()
        .filter(|(id, _)| !previous_map.contains_key(id) && !replaced_lane_ids.contains(id))
        .map(|(_, entry)| *entry)
        .collect();
    let retired = previous_map
        .iter()
        .filter(|(id, _)| !current_map.contains_key(id) && !replaced_lane_ids.contains(id))
        .map(|(_, entry)| *entry)
        .collect();

    let relabelled = current_map
        .iter()
        .filter_map(|(id, current_entry)| {
            if replaced_lane_ids.contains(id) {
                return None;
            }
            previous_map.get(id).and_then(|previous_entry| {
                (previous_entry.kura_segment != current_entry.kura_segment)
                    .then_some((*previous_entry, *current_entry))
            })
        })
        .collect();

    LaneTopologyDiff {
        added,
        retired,
        replacements,
        relabelled,
    }
}

static DEFAULT_TEST_CHAIN_ID: LazyLock<iroha_data_model::ChainId> = LazyLock::new(|| {
    use iroha_config::{base::read::ConfigReader, parameters::user};

    let config_path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../iroha_config/iroha_test_config.toml");

    let reader = ConfigReader::new()
        .read_toml_with_extends(&config_path)
        .unwrap_or_else(|err| {
            panic!(
                "failed to read default testing config `{}`: {err:?}",
                config_path.display()
            )
        });
    let user_config = user::Root::read_and_complete(reader).unwrap_or_else(|err| {
        panic!(
            "default testing config `{}` is incomplete: {err:?}",
            config_path.display()
        )
    });

    user_config
        .parse()
        .unwrap_or_else(|err| {
            panic!(
                "failed to parse default testing config `{}`: {err}",
                config_path.display()
            )
        })
        .common
        .chain
});

fn sumeragi_npos_parameters_from_parameters(params: &Parameters) -> Option<SumeragiNposParameters> {
    let id = SumeragiNposParameters::parameter_id();
    let custom = params.custom().get(&id)?;
    if let Some(parsed) = SumeragiNposParameters::from_custom_parameter(custom) {
        return Some(parsed);
    }
    let payload = custom.payload();
    let payload_preview: String = payload.get().chars().take(256).collect();

    match payload.try_into_any_norito::<SumeragiNposParameters>() {
        Ok(parsed) if parsed.validate().is_ok() => Some(parsed),
        Ok(parsed) => {
            warn!(
                error = ?parsed.validate().expect_err("invalid branch checked above"),
                "Rejected invalid `sumeragi_npos_parameters` custom parameter payload; payload_preview={payload_preview}"
            );
            None
        }
        Err(error) => {
            warn!(
                ?error,
                "Failed to decode `sumeragi_npos_parameters` custom parameter payload; payload_preview={payload_preview}"
            );
            None
        }
    }
}

/// Read the per-block gas limit from on-chain parameters, falling back to defaults on errors.
pub(crate) fn gas_limit_from_parameters(params: &Parameters) -> u64 {
    use core::str::FromStr;

    let name = match iroha_data_model::name::Name::from_str("ivm_gas_limit_per_block") {
        Ok(name) => name,
        Err(error) => {
            warn!(?error, "Failed to parse hardcoded gas limit parameter name");
            return DEFAULT_GAS_LIMIT_PER_BLOCK;
        }
    };

    let id = CustomParameterId::new(name);
    let Some(custom) = params.custom().get(&id) else {
        return DEFAULT_GAS_LIMIT_PER_BLOCK;
    };

    match custom.payload().try_into_any_norito::<u64>() {
        Ok(value) if value > 0 => value,
        Ok(value) => {
            warn!(value, "Ignoring non-positive ivm gas limit parameter");
            DEFAULT_GAS_LIMIT_PER_BLOCK
        }
        Err(error) => {
            warn!(
                ?error,
                "Failed to decode ivm gas limit parameter payload as u64"
            );
            DEFAULT_GAS_LIMIT_PER_BLOCK
        }
    }
}

fn block_proofs_for_entry_from_kura(
    kura: &Kura,
    block_height: NonZeroU64,
    entry_hash: HashOf<TransactionEntrypoint>,
) -> Result<BlockProofs, BlockProofError> {
    let height_usize: usize = block_height
        .get()
        .try_into()
        .map_err(|_| BlockProofError::HeightOutOfRange(block_height))?;
    let height = NonZeroUsize::new(height_usize).ok_or(BlockProofError::ZeroHeight)?;
    let block = kura
        .get_block(height)
        .ok_or(BlockProofError::BlockNotFound(block_height))?;

    let header = block.header();
    if header.height() != block_height {
        return Err(BlockProofError::BlockHeightMismatch {
            requested: block_height,
            actual: header.height(),
        });
    }
    let block_hash = block.hash();
    let executed_block_wire_hash = block
        .executed_block_wire_hash()
        .map_err(|_| BlockProofError::ExecutedBlockWireHashUnavailable(block_height))?;
    if !block.has_results() {
        return Err(BlockProofError::MissingResults(block_height));
    }
    let entry_hashes: Vec<_> = block.entrypoint_hashes().collect();
    let (entry_index, _) = entry_hashes
        .iter()
        .enumerate()
        .find(|(_, hash)| **hash == entry_hash)
        .ok_or(BlockProofError::EntrypointNotFound {
            entry_hash,
            block_height,
        })?;

    let entry_index_u32: u32 =
        entry_index
            .try_into()
            .map_err(|_| BlockProofError::MerkleProofUnavailable {
                entry_hash,
                block_height,
            })?;

    let expected_root =
        block
            .full_entry_merkle_root()
            .ok_or(BlockProofError::MerkleProofUnavailable {
                entry_hash,
                block_height,
            })?;
    let stored_entry_commitment =
        block
            .full_entry_merkle_commitment()
            .ok_or(BlockProofError::MerkleProofUnavailable {
                entry_hash,
                block_height,
            })?;
    let entry_merkle: CanonMerkleTree<_> = entry_hashes.iter().copied().collect();
    let entry_commitment = entry_merkle
        .commitment()
        .filter(|commitment| {
            commitment.root() == &expected_root && commitment == &stored_entry_commitment
        })
        .ok_or(BlockProofError::MerkleProofUnavailable {
            entry_hash,
            block_height,
        })?;
    let entry_receipt_proof =
        entry_merkle
            .get_proof(entry_index_u32)
            .ok_or(BlockProofError::MerkleProofUnavailable {
                entry_hash,
                block_height,
            })?;

    let entry_receipt = BlockReceiptProof::new(entry_hash, entry_receipt_proof);

    let expected_result_root =
        header
            .result_merkle_root()
            .ok_or(BlockProofError::ExecutionResultMissing {
                entry_hash,
                block_height,
            })?;
    let result_hashes: Vec<_> = block.result_hashes().collect();
    let result_hash =
        *result_hashes
            .get(entry_index)
            .ok_or(BlockProofError::ExecutionResultMissing {
                entry_hash,
                block_height,
            })?;
    let result_merkle: CanonMerkleTree<_> = result_hashes.iter().copied().collect();
    let stored_result_commitment =
        block
            .result_merkle_commitment()
            .ok_or(BlockProofError::ExecutionResultMissing {
                entry_hash,
                block_height,
            })?;
    let result_commitment = result_merkle
        .commitment()
        .filter(|commitment| {
            commitment.root() == &expected_result_root
                && commitment == &stored_result_commitment
                && commitment.leaf_count() == entry_commitment.leaf_count()
        })
        .ok_or(BlockProofError::ExecutionResultMissing {
            entry_hash,
            block_height,
        })?;
    let result_proof = result_merkle.get_proof(entry_index_u32).ok_or(
        BlockProofError::ExecutionResultMissing {
            entry_hash,
            block_height,
        },
    )?;
    let result_receipt = ExecutionReceiptProof::new(result_hash, result_proof);

    Ok(BlockProofs {
        block_height: header.height(),
        block_hash,
        executed_block_wire_hash,
        entry_hash,
        entry_commitment,
        entry_proof: entry_receipt,
        result_commitment,
        result_proof: result_receipt,
        fastpq_transcripts: block.fastpq_transcripts().clone(),
    })
}

/// Canonical read-only snapshot interface for world-state consumers.
///
/// Provides immutable access to world data and consensus topology metadata
/// without exposing pipeline or executor internals. This is the narrow surface
/// consumed by queries, Sumeragi, and the CLI when they only need a snapshot of
/// the WSV.
pub trait WorldStateSnapshot {
    /// Read-only access to the world state.
    fn world(&self) -> &impl WorldReadOnly;
    /// Recent block hashes for consistency checks.
    fn block_hashes(&self) -> &[HashOf<BlockHeader>];
    /// Current commit topology (ordering of peers).
    fn commit_topology(&self) -> &[PeerId];
    /// Previous commit topology (before the latest block).
    fn prev_commit_topology(&self) -> &[PeerId];
}

/// Read-only view over state-level resources (block/transaction/view).
pub trait StateReadOnly: WorldStateSnapshot {
    /// Merge-ledger cache for recent entries.
    fn merge_ledger(&self) -> &MergeLedgerStore;
    /// Iroha Virtual Machine instance.
    fn ivm(&self) -> &IVM;
    /// Shared immutable prepared-contract store for content-addressed hot paths.
    fn prepared_contract_cache(&self) -> PreparedContractCache;
    /// Block storage backend.
    fn kura(&self) -> &Kura;
    /// Live query store handle.
    fn query_handle(&self) -> &LiveQueryStoreHandle;
    /// Telemetry metrics handle (if enabled).
    #[cfg(feature = "telemetry")]
    fn metrics(&self) -> &StateTelemetry;

    /// Current block height derived from the block-hash journal.
    fn height(&self) -> usize {
        self.block_hashes().len()
    }

    /// Build the exact privacy capability snapshot from this committed view.
    ///
    /// # Errors
    ///
    /// Returns a deterministic validation error if persisted privacy state is
    /// inconsistent with this view's committed height or compiled profiles.
    fn privacy_capability_snapshot_v1(
        &self,
    ) -> core::result::Result<
        iroha_data_model::privacy::PrivacyCapabilitySnapshotV1,
        iroha_data_model::privacy::PrivacyCapabilitySnapshotValidationErrorV1,
    > {
        let committed_height = u64::try_from(self.height())
            .expect("supported target pointer widths always fit a state height into u64");
        let world = self.world();
        crate::privacy_profiles::committed_privacy_capability_snapshot_v1(
            committed_height,
            *world.privacy_consensus_policy(),
            |protocol_id| {
                world
                    .privacy_activations()
                    .get(&crate::privacy_state::PrivacyActivationKeyV1::new(
                        protocol_id,
                    ))
                    .copied()
            },
        )
    }

    /// Latest committed block hash (if any).
    fn latest_block_hash(&self) -> Option<HashOf<BlockHeader>> {
        self.block_hashes().iter().nth_back(0).copied()
    }

    /// Previous block hash (if at least two blocks are committed).
    fn prev_block_hash(&self) -> Option<HashOf<BlockHeader>> {
        self.block_hashes().iter().nth_back(1).copied()
    }

    /// Pipeline execution preferences (dynamic prepass, overlays, pointer‑ABI policy, etc.).
    fn pipeline(&self) -> &iroha_config::parameters::actual::Pipeline;
    /// Oracle aggregation configuration snapshot.
    fn oracle(&self) -> &iroha_config::parameters::actual::Oracle;
    /// Cryptography configuration (enabled algorithms, defaults).
    fn crypto(&self) -> Arc<iroha_config::parameters::actual::Crypto>;
    /// Nexus configuration snapshot (lanes, fusion, DA sampling policies).
    fn nexus(&self) -> &iroha_config::parameters::actual::Nexus;
    /// Resolve the non-zero incarnation of an active lane at a proposal height.
    fn lane_incarnation_at_height(&self, lane_id: LaneId, proposal_height: u64) -> Option<Hash>;
    /// Content lane configuration snapshot.
    fn content(&self) -> &iroha_config::parameters::actual::Content;
    /// Zero-knowledge verification settings (Halo2 backend, curve, limits).
    fn zk(&self) -> &iroha_config::parameters::actual::Zk;
    /// Immutable governed SCCP registry for this state snapshot.
    fn sccp_registry(&self) -> &ValidatedSccpRegistryV1;
    /// Chain identifier bound to this state view.
    fn chain_id(&self) -> &iroha_data_model::ChainId;
    /// Snapshot of per-dataspace AXT policies available to hosts/admission.
    fn axt_policy_snapshot(&self) -> iroha_data_model::nexus::AxtPolicySnapshot
    where
        Self: Sized,
    {
        crate::smartcontracts::ivm::host::CoreHost::axt_policy_snapshot_from_state(self)
            .unwrap_or_default()
    }

    /// Cached snapshot of all account identifiers currently known to the state view.
    fn accounts_snapshot(&self) -> Arc<Vec<AccountId>>;

    /// Resolve authoritative validator peer ids for a lane from the snapshot.
    fn authoritative_lane_peer_ids(&self, lane_id: LaneId) -> Vec<PeerId>;

    /// Resolve authoritative validator peer ids for a lane at an explicit
    /// consensus height.
    ///
    /// Callers validating a proposed height must not silently substitute the
    /// pre-state height: key activation, lane lifecycle, and autoscale
    /// ownership are height-sensitive consensus inputs.
    fn authoritative_lane_peer_ids_at_height(
        &self,
        lane_id: LaneId,
        block_height: u64,
    ) -> Vec<PeerId>;

    /// Get a reference to the block one before the latest block.
    /// Returns None if at least 2 blocks are not committed.
    ///
    /// If you only need hash of the latest block prefer using [`Self::prev_block_hash`].
    #[inline]
    fn prev_block(&self) -> Option<Arc<SignedBlock>> {
        self.height()
            .checked_sub(1)
            .and_then(NonZeroUsize::new)
            .and_then(|height| self.kura().get_block(height))
    }

    /// Get a reference to the latest block. Returns none if genesis is not committed.
    ///
    /// If you only need hash of the latest block prefer using [`Self::latest_block_hash`]
    #[inline]
    fn latest_block(&self) -> Option<Arc<SignedBlock>> {
        NonZeroUsize::new(self.height()).and_then(|height| self.kura().get_block(height))
    }

    /// Load all blocks in the block chain from disk, skipping missing Kura entries.
    fn all_blocks(
        &self,
        start: NonZeroUsize,
    ) -> impl DoubleEndedIterator<Item = Arc<SignedBlock>> + '_ {
        (start.get()..=self.height()).filter_map(|height| {
            let height = NonZeroUsize::new(height)?;
            if self.kura().is_hash_only_block_height(height) {
                return None;
            }
            self.kura().get_block(height).map_or_else(
                || {
                    warn!(
                        height = height.get(),
                        "missing block in Kura; skipping entry"
                    );
                    None
                },
                Some,
            )
        })
    }

    /// Produce Merkle proofs for an entrypoint hash at the given block height.
    ///
    /// # Errors
    /// Returns [`BlockProofError`] when the referenced block cannot be found, lacks
    /// execution results, the Merkle proof cannot be constructed, or the provided
    /// height does not fit into the host pointer width.
    fn block_proofs_for_entry(
        &self,
        block_height: NonZeroU64,
        entry_hash: HashOf<TransactionEntrypoint>,
    ) -> Result<BlockProofs, BlockProofError> {
        block_proofs_for_entry_from_kura(self.kura(), block_height, entry_hash)
    }

    /// Returns [`Some`] milliseconds since the genesis block was
    /// committed, or [`None`] if it wasn't.
    #[inline]
    fn genesis_timestamp(&self) -> Option<Duration> {
        if self.block_hashes().is_empty() {
            None
        } else if self.kura().is_hash_only_block_height(nonzero!(1_usize)) {
            debug!(
                "genesis block body is hash-only from snapshot bootstrap; uptime timestamp unavailable"
            );
            None
        } else {
            let opt = self
                .kura()
                .get_block(nonzero!(1_usize))
                .map(|genesis_block| genesis_block.header().creation_time());

            if opt.is_none() {
                error!("Failed to get genesis block from Kura.");
            }

            opt
        }
    }
}

macro_rules! impl_state_ro {
    ($($ident:ty),*) => {$(
        impl WorldStateSnapshot for $ident {
            fn world(&self) -> &impl WorldReadOnly {
                &self.world
            }
            fn block_hashes(&self) -> &[HashOf<BlockHeader>] {
                &self.block_hashes
            }
            fn commit_topology(&self) -> &[PeerId] {
                &self.commit_topology
            }
            fn prev_commit_topology(&self) -> &[PeerId] {
                &self.prev_commit_topology
            }
        }

        impl StateReadOnly for $ident {
            fn merge_ledger(&self) -> &MergeLedgerStore {
                self.merge_ledger
            }
            fn ivm(&self) -> &IVM {
                &self.ivm
            }
            fn prepared_contract_cache(&self) -> PreparedContractCache {
                self.pipeline_ivm_prepared_cache.clone()
            }
            fn kura(&self) -> &Kura {
                &self.kura
            }
            fn query_handle(&self) -> &LiveQueryStoreHandle {
                &self.query_handle
            }
            #[cfg(feature = "telemetry")]
            fn metrics(&self) -> &StateTelemetry {
                &self.telemetry
            }
            fn pipeline(&self) -> &iroha_config::parameters::actual::Pipeline {
                &self.pipeline
            }
            fn oracle(&self) -> &iroha_config::parameters::actual::Oracle {
                &self.oracle
            }
            fn crypto(&self) -> Arc<iroha_config::parameters::actual::Crypto> {
                self.crypto.clone()
            }
            fn nexus(&self) -> &iroha_config::parameters::actual::Nexus {
                &self.nexus
            }
            fn lane_incarnation_at_height(
                &self,
                lane_id: LaneId,
                proposal_height: u64,
            ) -> Option<Hash> {
                consensus_lane_dataspace_at_height(lane_id, &self.nexus, proposal_height)?;
                let lane = self
                    .nexus
                    .lane_catalog
                    .lanes()
                    .iter()
                    .find(|lane| lane.id == lane_id)?;
                let activation_height = self
                    .lane_incarnation_activation_heights
                    .get(&lane_id)
                    .copied()?;
                if proposal_height <= activation_height {
                    return None;
                }
                let incarnation = self
                    .lane_incarnations
                    .get(&lane_id)
                    .copied()
                    .filter(|incarnation| !lane_incarnation_is_zero(*incarnation))?;
                if let Some(drain_state) = decode_autoscale_lane_drain_state(lane).ok().flatten()
                    && !autoscale_lane_drain_state_matches_context(
                        lane,
                        &drain_state,
                        &self.chain_id,
                        incarnation,
                    )
                {
                    return None;
                }
                Some(incarnation)
            }
            fn content(&self) -> &iroha_config::parameters::actual::Content {
                &self.content
            }
            fn zk(&self) -> &iroha_config::parameters::actual::Zk {
                &self.zk
            }
            fn sccp_registry(&self) -> &ValidatedSccpRegistryV1 {
                &self.sccp_registry
            }
            fn chain_id(&self) -> &iroha_data_model::ChainId {
                &self.chain_id
            }
            fn accounts_snapshot(&self) -> Arc<Vec<AccountId>> {
                Arc::clone(self.accounts_snapshot_cache.get_or_init(|| {
                    Arc::new(
                        self.world
                            .accounts_iter()
                            .map(|entry| entry.id().clone())
                            .collect(),
                    )
                }))
            }
            fn authoritative_lane_peer_ids(&self, lane_id: LaneId) -> Vec<PeerId> {
                let block_height = u64::try_from(self.height()).unwrap_or(u64::MAX);
                self.authoritative_lane_peer_ids_at_height(lane_id, block_height)
            }
            fn authoritative_lane_peer_ids_at_height(
                &self,
                lane_id: LaneId,
                block_height: u64,
            ) -> Vec<PeerId> {
                let validator_mode = self.nexus.staking.validator_mode(lane_id, &self.nexus.lane_catalog);
                State::authoritative_lane_peer_ids_from_sources(
                    self.world(),
                    self.chain_id(),
                    lane_id,
                    validator_mode,
                    self.lane_manifests.as_ref(),
                    &self.nexus,
                    self.commit_topology(),
                    block_height,
                )
            }
        }
    )*};
}

#[derive(Clone)]
enum ConfidentialRegistryItem {
    VerifyingKey(iroha_data_model::proof::VerifyingKeyId),
    Pedersen(iroha_data_model::confidential::ConfidentialParamsId),
    Poseidon(iroha_data_model::confidential::ConfidentialParamsId),
}

#[derive(Clone)]
struct ConfidentialTransition {
    item: ConfidentialRegistryItem,
    new_status: iroha_data_model::confidential::ConfidentialStatus,
}

fn project_confidential_status(
    current: iroha_data_model::confidential::ConfidentialStatus,
    activation_height: Option<u64>,
    withdraw_height: Option<u64>,
    height: u64,
) -> iroha_data_model::confidential::ConfidentialStatus {
    if let Some(withdraw) = withdraw_height
        && height >= withdraw
    {
        ConfidentialStatus::Withdrawn
    } else if let Some(activation) = activation_height
        && height >= activation
    {
        ConfidentialStatus::Active
    } else {
        current
    }
}

fn collect_confidential_transitions(
    world: &impl WorldReadOnly,
    height: u64,
) -> Vec<ConfidentialTransition> {
    let mut transitions = Vec::new();

    for (id, rec) in world.verifying_keys().iter() {
        let target = project_confidential_status(
            rec.status,
            rec.activation_height,
            rec.withdraw_height,
            height,
        );
        if target != rec.status {
            transitions.push(ConfidentialTransition {
                item: ConfidentialRegistryItem::VerifyingKey(id.clone()),
                new_status: target,
            });
        }
    }

    for (id, rec) in world.pedersen_params().iter() {
        let target = project_confidential_status(
            rec.status,
            rec.activation_height,
            rec.withdraw_height,
            height,
        );
        if target != rec.status {
            transitions.push(ConfidentialTransition {
                item: ConfidentialRegistryItem::Pedersen(*id),
                new_status: target,
            });
        }
    }

    for (id, rec) in world.poseidon_params().iter() {
        let target = project_confidential_status(
            rec.status,
            rec.activation_height,
            rec.withdraw_height,
            height,
        );
        if target != rec.status {
            transitions.push(ConfidentialTransition {
                item: ConfidentialRegistryItem::Poseidon(*id),
                new_status: target,
            });
        }
    }

    transitions.sort_by(|a, b| {
        use ConfidentialRegistryItem::{Pedersen, Poseidon, VerifyingKey};

        let rank = |item: &ConfidentialRegistryItem| match item {
            VerifyingKey(_) => 0u8,
            Pedersen(_) => 1,
            Poseidon(_) => 2,
        };

        rank(&a.item)
            .cmp(&rank(&b.item))
            .then_with(|| match (&a.item, &b.item) {
                (VerifyingKey(a_id), VerifyingKey(b_id)) => a_id
                    .backend
                    .as_str()
                    .cmp(b_id.backend.as_str())
                    .then_with(|| a_id.name.cmp(&b_id.name)),
                (Pedersen(a_id), Pedersen(b_id)) | (Poseidon(a_id), Poseidon(b_id)) => {
                    a_id.get().cmp(&b_id.get())
                }
                _ => std::cmp::Ordering::Equal,
            })
    });

    transitions
}

fn apply_confidential_transitions(
    world_tx: &mut WorldTransaction<'_, '_>,
    transitions: &[ConfidentialTransition],
    delta_limit: u32,
) -> usize {
    let mut applied = 0usize;
    let cap = if delta_limit == 0 {
        usize::MAX
    } else {
        delta_limit as usize
    };

    for transition in transitions {
        if applied >= cap {
            break;
        }
        match &transition.item {
            ConfidentialRegistryItem::VerifyingKey(id) => {
                if let Some(mut rec) = world_tx.verifying_keys.get(id).cloned() {
                    let circuit_key = (rec.circuit_id.clone(), rec.version);
                    rec.status = transition.new_status;
                    if matches!(
                        transition.new_status,
                        iroha_data_model::confidential::ConfidentialStatus::Withdrawn
                    ) {
                        rec.key = None;
                        rec.vk_len = 0;
                    }
                    world_tx.verifying_keys.remove(id.clone());
                    world_tx
                        .verifying_keys_by_circuit
                        .remove(circuit_key.clone());
                    world_tx.verifying_keys.insert(id.clone(), rec);
                    world_tx
                        .verifying_keys_by_circuit
                        .insert(circuit_key, id.clone());
                    applied = applied.saturating_add(1);
                }
            }
            ConfidentialRegistryItem::Pedersen(id) => {
                if let Some(mut rec) = world_tx.pedersen_params.get(id).cloned() {
                    rec.status = transition.new_status;
                    world_tx.pedersen_params.remove(*id);
                    world_tx.pedersen_params.insert(*id, rec);
                    applied = applied.saturating_add(1);
                }
            }
            ConfidentialRegistryItem::Poseidon(id) => {
                if let Some(mut rec) = world_tx.poseidon_params.get(id).cloned() {
                    rec.status = transition.new_status;
                    world_tx.poseidon_params.remove(*id);
                    world_tx.poseidon_params.insert(*id, rec);
                    applied = applied.saturating_add(1);
                }
            }
        }
    }

    applied
}

fn compute_final_confidential_statuses(
    world: &impl WorldReadOnly,
    transitions: &[ConfidentialTransition],
    delta_limit: u32,
) -> (
    std::collections::BTreeMap<
        iroha_data_model::proof::VerifyingKeyId,
        iroha_data_model::confidential::ConfidentialStatus,
    >,
    std::collections::BTreeMap<
        iroha_data_model::confidential::ConfidentialParamsId,
        iroha_data_model::confidential::ConfidentialStatus,
    >,
    std::collections::BTreeMap<
        iroha_data_model::confidential::ConfidentialParamsId,
        iroha_data_model::confidential::ConfidentialStatus,
    >,
) {
    let mut vk_statuses = world
        .verifying_keys()
        .iter()
        .map(|(id, rec)| (id.clone(), rec.status))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut pedersen_statuses = world
        .pedersen_params()
        .iter()
        .map(|(id, rec)| (*id, rec.status))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut poseidon_statuses = world
        .poseidon_params()
        .iter()
        .map(|(id, rec)| (*id, rec.status))
        .collect::<std::collections::BTreeMap<_, _>>();

    let cap = if delta_limit == 0 {
        usize::MAX
    } else {
        delta_limit as usize
    };

    for (idx, transition) in transitions.iter().enumerate() {
        if idx >= cap {
            break;
        }
        match &transition.item {
            ConfidentialRegistryItem::VerifyingKey(id) => {
                vk_statuses.insert(id.clone(), transition.new_status);
            }
            ConfidentialRegistryItem::Pedersen(id) => {
                pedersen_statuses.insert(*id, transition.new_status);
            }
            ConfidentialRegistryItem::Poseidon(id) => {
                poseidon_statuses.insert(*id, transition.new_status);
            }
        }
    }

    (vk_statuses, pedersen_statuses, poseidon_statuses)
}

fn compute_vk_set_hash_from_statuses(
    world: &impl WorldReadOnly,
    statuses: &std::collections::BTreeMap<
        iroha_data_model::proof::VerifyingKeyId,
        iroha_data_model::confidential::ConfidentialStatus,
    >,
) -> Option<[u8; 32]> {
    compute_vk_set_hash_from_statuses_at_height(world, statuses, None)
}

fn compute_vk_set_hash_from_statuses_at_height(
    world: &impl WorldReadOnly,
    statuses: &std::collections::BTreeMap<
        iroha_data_model::proof::VerifyingKeyId,
        iroha_data_model::confidential::ConfidentialStatus,
    >,
    height: Option<u64>,
) -> Option<[u8; 32]> {
    use iroha_data_model::confidential::ConfidentialStatus;

    let mut entries: Vec<_> = world
        .verifying_keys()
        .iter()
        .filter(|(id, rec)| {
            let status = statuses.get(*id).copied().unwrap_or(rec.status);
            if let Some(height) = height {
                params_effective(status, rec.activation_height, rec.withdraw_height, height)
            } else {
                matches!(status, ConfidentialStatus::Active)
            }
        })
        .collect();

    if entries.is_empty() {
        return None;
    }

    entries.sort_by(|(id_a, rec_a), (id_b, rec_b)| {
        let backend_cmp = id_a.backend.as_str().cmp(id_b.backend.as_str());
        if backend_cmp != std::cmp::Ordering::Equal {
            return backend_cmp;
        }
        rec_a
            .circuit_id
            .cmp(&rec_b.circuit_id)
            .then(rec_a.version.cmp(&rec_b.version))
            .then(id_a.name.cmp(&id_b.name))
    });

    let mut buf = Vec::with_capacity(entries.len() * 160);
    for (id, rec) in entries {
        let backend: &str = id.backend.as_ref();
        buf.extend_from_slice(backend.as_bytes());
        buf.push(0);
        buf.extend_from_slice(id.name.as_bytes());
        buf.push(0);
        buf.extend_from_slice(rec.circuit_id.as_bytes());
        buf.push(0);
        buf.extend_from_slice(&rec.version.to_le_bytes());
        buf.extend_from_slice(&rec.commitment);
        buf.extend_from_slice(&rec.public_inputs_schema_hash);
        if let Some(ref gas) = rec.gas_schedule_id {
            buf.extend_from_slice(gas.as_bytes());
        }
        buf.push(0xFF);
    }

    Some(iroha_crypto::Hash::new(&buf).into())
}

fn params_effective(
    status: iroha_data_model::confidential::ConfidentialStatus,
    activation_height: Option<u64>,
    withdraw_height: Option<u64>,
    height: u64,
) -> bool {
    use iroha_data_model::confidential::ConfidentialStatus;

    matches!(status, ConfidentialStatus::Active)
        && activation_height.is_none_or(|h| height >= h)
        && withdraw_height.is_none_or(|h| height < h)
}

/// Compute a deterministic hash of all active verifying-key registry entries in the current world state.
#[must_use]
pub fn compute_vk_set_hash(world: &impl WorldReadOnly) -> Option<[u8; 32]> {
    let statuses = world
        .verifying_keys()
        .iter()
        .map(|(id, rec)| (id.clone(), rec.status))
        .collect::<std::collections::BTreeMap<_, _>>();
    compute_vk_set_hash_from_statuses(world, &statuses)
}

/// Compute a deterministic hash of verifying-key entries effective at `height`.
#[must_use]
pub fn compute_vk_set_hash_at_height(world: &impl WorldReadOnly, height: u64) -> Option<[u8; 32]> {
    let statuses = world
        .verifying_keys()
        .iter()
        .map(|(id, rec)| (id.clone(), rec.status))
        .collect::<std::collections::BTreeMap<_, _>>();
    compute_vk_set_hash_from_statuses_at_height(world, &statuses, Some(height))
}

