    #[test]
    fn pending_contract_upload_roundtrips_in_state_snapshot_without_legacy_defaults() {
        let authority = AccountId::new(checked_keypair().public_key().clone());
        let code_hash = iroha_crypto::Hash::new(b"partial contract upload snapshot");
        let upload_key = SmartContractCodeUploadKey::new(authority, code_hash);
        let chunk_key = SmartContractCodeUploadChunkKey::new(upload_key.clone(), 1);
        let descriptor = SmartContractCodeUploadDescriptor {
            total_size: 65_539,
            chunk_count: 2,
        };
        let mut world = World::default();
        world
            .contract_code_uploads
            .insert(upload_key.clone(), descriptor);
        world
            .contract_code_upload_chunks
            .insert(chunk_key.clone(), vec![7, 8, 9]);

        let decoded = decode_sccp_world_snapshot(world).expect("decode pending upload snapshot");
        let view = decoded.view();
        assert_eq!(
            view.world.contract_code_uploads.get(&upload_key),
            Some(&descriptor)
        );
        assert_eq!(
            view.world.contract_code_upload_chunks.get(&chunk_key),
            Some(&vec![7, 8, 9])
        );

        for field in ["contract_code_uploads", "contract_code_upload_chunks"] {
            let mut snapshot = sccp_state_snapshot_value(World::default(), SCCP_SNAPSHOT_CHAIN_ID);
            state_snapshot_world_mut(&mut snapshot).remove(field);
            let error = decode_state_snapshot_value(snapshot)
                .err()
                .unwrap_or_else(|| panic!("snapshot missing {field} must fail"));
            assert!(
                error.to_string().contains(field),
                "missing required {field} produced unexpected error: {error}"
            );
        }
    }

    #[test]
    fn provider_ingest_completion_authority_snapshot_is_required_and_owner_bound() {
        let owner = AccountId::new(checked_keypair().public_key().clone());
        let provider_id = ProviderId::new([0xA1; 32]);
        let authority = ProviderIngestCompletionAuthorityV1::new(
            owner.clone(),
            iroha_data_model::sorafs::pin_registry::ProviderIngestCompletionSignerPolicyV1 {
                policy_id: [0xA2; 32],
                revision: 1,
                predecessor_digest: None,
                policy_digest: [0xA3; 32],
            },
        );
        let mut world = World::default();
        let (owner_id, owner_value) = iroha_data_model::account::Account::new(owner.clone())
            .build(&owner)
            .into_key_value();
        world.accounts.insert(owner_id, owner_value);
        world.provider_owners.insert(provider_id, owner);
        world
            .provider_ingest_completion_authorities
            .insert(provider_id, authority.clone());

        let decoded =
            decode_sccp_world_snapshot(world).expect("decode completion-authority snapshot");
        assert_eq!(
            decoded
                .view()
                .world
                .provider_ingest_completion_authorities
                .get(&provider_id),
            Some(&authority)
        );

        for field in ["provider_owners", "provider_ingest_completion_authorities"] {
            let mut snapshot = sccp_state_snapshot_value(World::default(), SCCP_SNAPSHOT_CHAIN_ID);
            state_snapshot_world_mut(&mut snapshot).remove(field);
            let error = decode_state_snapshot_value(snapshot)
                .err()
                .unwrap_or_else(|| panic!("snapshot missing {field} must fail"));
            assert!(
                error.to_string().contains(field),
                "missing required {field} produced unexpected error: {error}"
            );
        }

        let mut mismatched = World::default();
        mismatched
            .provider_ingest_completion_authorities
            .insert(provider_id, authority);
        let error = match decode_sccp_world_snapshot(mismatched) {
            Ok(_) => panic!("completion authority without its registered owner must fail"),
            Err(error) => error,
        };
        assert!(
            error
                .to_string()
                .contains("provider_ingest_completion_authorities"),
            "owner mismatch produced unexpected error: {error}"
        );
    }

    #[test]
    fn musubi_domain_ownership_generation_snapshot_is_required_and_canonical() {
        let domain = DomainId::try_new("packages", "universal").expect("domain id");
        let mut world = World::default();
        world
            .musubi_domain_ownership_generations
            .insert(domain.clone(), 4);

        let decoded =
            decode_sccp_world_snapshot(world).expect("decode canonical Musubi generation snapshot");
        assert_eq!(
            decoded
                .view()
                .world
                .musubi_domain_ownership_generations
                .get(&domain),
            Some(&4)
        );

        let mut missing = sccp_state_snapshot_value(World::default(), SCCP_SNAPSHOT_CHAIN_ID);
        assert!(
            state_snapshot_world_mut(&mut missing)
                .remove("musubi_domain_ownership_generations")
                .is_some()
        );
        let error = decode_state_snapshot_value(missing)
            .err()
            .expect("missing Musubi generation map must fail");
        assert!(
            error
                .to_string()
                .contains("musubi_domain_ownership_generations"),
            "unexpected missing-field error: {error}"
        );

        for generation in [0, 1] {
            let mut world = World::default();
            world
                .musubi_domain_ownership_generations
                .insert(domain.clone(), generation);
            let error = match decode_sccp_world_snapshot(world) {
                Ok(_) => panic!("persisted Musubi generation {generation} must fail"),
                Err(error) => error,
            };
            assert!(
                error
                    .to_string()
                    .contains("musubi_domain_ownership_generations"),
                "unexpected generation {generation} error: {error}"
            );
        }
    }

